@dataclass
class Signal:
    action: str  # e.g., 'OPEN', 'AUGMENT', 'REDUCE', 'PROFIT_TAKE', 'REVERSE', 'NO_ACTION', 'CLOSE'
    reason: str  # A descriptive reason for the signal
    conviction: float  # A score from -100 (strong sell) to +100 (strong b
    quantity: float = 0.0
    reduction_amount: float = 0.0
    stop_levels: Optional[List[Dict[str, float]]] = None

def _convert_timestamp_strings_positions(data: Any) -> Any:
    """Recursively convert all timestamp strings in dict/list to datetime objects - CRITICAL for all JSON loads"""
    if isinstance(data, dict):
        result = {}
        for key, value in data.items():
            if isinstance(value, str) and any(ts_key in key.lower() for ts_key in ['time', 'timestamp', 'updated', 'at', 'date']):
                try:
                    if 'T' in value and ('Z' in value or '+' in value or value.count('-') >= 2):
                        from dateutil.parser import isoparse
                        parsed = isoparse(value)
                        result[key] = parsed.replace(tzinfo=timezone.utc) if parsed.tzinfo is None else parsed
                    else:
                        result[key] = value
                except (ValueError, TypeError):
                    try:
                        parsed = pd.to_datetime(value, utc=True).to_pydatetime()
                        result[key] = parsed.replace(tzinfo=timezone.utc) if parsed.tzinfo is None else parsed
                    except (ValueError, TypeError):
                        result[key] = value
            elif isinstance(value, (dict, list)):
                result[key] = _convert_timestamp_strings_positions(value)
            else:
                result[key] = value
        return result
    elif isinstance(data, list):
        return [_convert_timestamp_strings_positions(item) for item in data]
    return data


@dataclass(slots=True)
class Position:
    symbol: str
    position_side: str
    entry_price: float
    mark_price: float
    positionAmt: float
    initial_quantity: float
    gain: float
    max_gain: float
    prev_gain: float
    max_quantity: float
    last_augmentation_amount: float
    last_augmentation_price: float
    last_augmentation_time: Optional[datetime]
    last_reduction_amount: float
    last_reduction_price: float
    last_reduction_time: Optional[datetime]
    max_positionSize: float
    opened_at: Optional[datetime]
    last_updated: Optional[datetime]
    last_signal: str
    realized_pnl: float = 0.0
    unrealized_pnl: float = 0.0
    was_reentered: bool = False
    was_reduced: bool = False
    prev_gain_last_updated: Optional[datetime] = None
    augment_reason: str = ""
    reduction_reason: str = ""
    mark_price_last_updated: Optional[datetime] = None

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "Position":
        if not isinstance(data, dict):
            raise TypeError(f"Position.from_dict() requires a dict, got {type(data).__name__}")
        data = _convert_timestamp_strings_positions(data)  # Convert all timestamp strings first
        def safe_float(x):
            if x is None:
                return 0.0
            if isinstance(x, (int, float, Decimal)):
                return float(x)
            if isinstance(x, str):
                s = x.strip()
                if s == "": return 0.0
                s = s.replace(",", "")
                try: return float(Decimal(s))
                except Exception: return 0.0
            if isinstance(x, dict):
                for k in ("amount", "qty", "positionAmt", "value"):
                    if k in x: return safe_float(x[k])
            try:
                return float(x)
            except (TypeError, ValueError):
                return 0.0
        def safe_time(x):
            if isinstance(x, datetime):
                return x
            if isinstance(x, str):
                try:
                    return pd.to_datetime(x, utc=True).to_pydatetime()
                except ValueError:
                    pass
            return None
        return cls(
            symbol=str(data.get("symbol", "")),
            position_side=str(data.get("position_side", "")),
            entry_price=safe_float(data.get("entry_price")),
            mark_price=safe_float(data.get("mark_price")),
            positionAmt=abs(safe_float(data.get("positionAmt")) or 0.0),
            initial_quantity=safe_float(data.get("initial_quantity")),
            gain=safe_float(data.get("gain")),
            max_gain=safe_float(data.get("max_gain")),
            prev_gain=safe_float(data.get("prev_gain")),
            max_quantity=safe_float(data.get("max_quantity")),
            last_augmentation_amount=safe_float(data.get("last_augmentation_amount")),
            last_augmentation_price=safe_float(data.get("last_augmentation_price")),
            last_augmentation_time=safe_time(data.get("last_augmentation_time")),
            last_reduction_amount=safe_float(data.get("last_reduction_amount")),
            last_reduction_price=safe_float(data.get("last_reduction_price")),
            last_reduction_time=safe_time(data.get("last_reduction_time")),
            max_positionSize=safe_float(data.get("max_positionSize")),
            opened_at=safe_time(data.get("opened_at")),
            last_updated=safe_time(data.get("last_updated")),
            last_signal=str(data.get("last_signal", "")),
            realized_pnl=(safe_float(data.get("realized_pnl"))),
            unrealized_pnl=safe_float(data.get("unrealized_pnl")),
            was_reentered=data.get("was_reentered", False),
            was_reduced=data.get("was_reduced", False),
            prev_gain_last_updated=safe_time(data.get("prev_gain_last_updated")),
            augment_reason=str(data.get("augment_reason", data.get("reason", ""))),
            reduction_reason=str(data.get("reduction_reason", data.get("reason", ""))),
            mark_price_last_updated=safe_time(data.get("mark_price_last_updated")), )

    def to_json(self) -> Dict[str, Any]:
        payload = asdict(self)
        for key, value in payload.items():
            if isinstance(value, datetime): payload[key] = value.strftime("%Y-%m-%dT%H:%M:%S.%fZ")
        if 'positionAmt' in payload:
            pos_amt_val = payload.get('positionAmt', 0) or 0
            payload['positionAmt'] = abs(safe_float(pos_amt_val, 0.0))
        return payload
    def to_dict(self) -> Dict[str, Any]:
        result = asdict(self)
        now = datetime.now(timezone.utc)
        for key, value in result.items():
            if isinstance(value, datetime):
                result[key] = value.strftime('%Y-%m-%dT%H:%M:%S.%fZ')
            elif value is None:
                result[key] = None
        # CRITICAL: Ensure positionAmt is always positive in dict output - sign is handled by position_side
        if 'positionAmt' in result:
            pos_amt_val = result.get('positionAmt', 0) or 0
            result['positionAmt'] = abs(safe_float(pos_amt_val, 0.0))
        # CRITICAL: If mark_price exists and is valid, ensure mark_price_last_updated is recent (within last 5 minutes)
        if result.get('mark_price') and result.get('mark_price') > 0:
            mark_updated_str = result.get('mark_price_last_updated')
            if mark_updated_str:
                try:
                    mark_dt = datetime.fromisoformat(mark_updated_str.replace('Z', '+00:00'))
                    age_seconds = (now - mark_dt).total_seconds()
                    if age_seconds > 300:  # Older than 5 minutes - update to now
                        result['mark_price_last_updated'] = now.strftime('%Y-%m-%dT%H:%M:%S.%fZ')
                except Exception:
                    result['mark_price_last_updated'] = now.strftime('%Y-%m-%dT%H:%M:%S.%fZ')
            else:
                result['mark_price_last_updated'] = now.strftime('%Y-%m-%dT%H:%M:%S.%fZ')
        return result

