    def _calculate_safe_stop_price(self, level: float, current_price: float, is_long: bool) -> float:
        buffer=self.price_buffer_pct
        return level*(1-buffer) if is_long else level*(1+buffer)
    def _calculate_min_stop_distance(self, entry_price: float, indicators: Dict[str, Any], is_long: bool, current_price: float = 0.0, position_gain: float = 0.0) -> float:
        if entry_price <= 0: return 0.0
        ema_20_std_3m = float(indicators.get("ema_20_std_3m", 0.0) or 0.0);atr_3m = float(indicators.get("atr_3m", 0.0) or 0.0); dc_low_3m=float(indicators.get('dc_low_3m', 0) or 0); dc_high_3m=float(indicators.get('dc_high_3m', 0) or 0)
        if is_long:
            dist1 = entry_price - dc_low_3m if dc_low_3m > 0 and entry_price > dc_low_3m else 0.0
        else:
            dist1 = dc_high_3m - entry_price if dc_high_3m > 0 and dc_high_3m > entry_price else 0.0
        dist2 = ema_20_std_3m / 2.0 if ema_20_std_3m > 0 else 0.0
        dist3 = atr_3m if atr_3m > 0 else 0.0
        if dist1 > 0 and current_price > 0 and entry_price > 0:
            breakeven_threshold = max(3.0 * atr_3m, entry_price * 0.006) if atr_3m > 0 else entry_price * 0.006
            price_moved_enough = (is_long and current_price >= entry_price + breakeven_threshold) or (not is_long and current_price <= entry_price - breakeven_threshold)
            if not price_moved_enough: return max(dist1, dist2, dist3)
            return max(dist2, dist3)
        return max(dist1, dist2, dist3)
    def _enforce_min_distance(self, stop_price: float, entry_price: float, min_distance: float, is_long: bool, initial_min_distance: Optional[float] = None, existing_stop_price: Optional[float] = None, dc_low_3m: float = 0.0, dc_high_3m: float = 0.0, current_price: float = 0.0, atr_3m: float = 0.0) -> float:
        if entry_price <= 0 or min_distance <= 0: return stop_price
        breakeven_allowed = False
        if current_price > 0 and entry_price > 0:
            breakeven_threshold = max(3.0 * atr_3m, entry_price * 0.006) if atr_3m > 0 else entry_price * 0.006
            breakeven_allowed = (is_long and current_price >= entry_price + breakeven_threshold) or (not is_long and current_price <= entry_price - breakeven_threshold)
        if is_long:
            min_allowed = entry_price - min_distance
            enforced = max(stop_price, min_allowed)
            if dc_low_3m > 0: enforced = min(enforced, dc_low_3m)
            if initial_min_distance and initial_min_distance > 0:
                initial_min_allowed = entry_price - initial_min_distance
                if existing_stop_price and existing_stop_price > 0:
                    if enforced > existing_stop_price:
                        return enforced
                    else:
                        return max(enforced, initial_min_allowed, existing_stop_price)
                return max(enforced, initial_min_allowed)
            return enforced
        else:
            max_allowed = entry_price + min_distance
            enforced = min(stop_price, max_allowed)
            if dc_high_3m > 0: enforced = max(enforced, dc_high_3m)
            if initial_min_distance and initial_min_distance > 0:
                initial_max_allowed = entry_price + initial_min_distance
                if existing_stop_price and existing_stop_price > 0:
                    if enforced < existing_stop_price:
                        return enforced
                    else:
                        return min(enforced, initial_max_allowed, existing_stop_price)
                return min(enforced, initial_max_allowed)
            return enforced
    def build_levels(self,*,position_key:str,position_side:str,positionAmt:float,current_price:float,indicators:Dict[str,Any],event:str="sync",position:Any=None) -> List[StopLevel]:
        is_long = position_side.upper() == "LONG"; now_ts = datetime.now(timezone.utc)
        if positionAmt <= 0.0 or current_price <= 0.0: return []
        ak, symbol, position_side = parse_position_key(position_key)
        min_qty = self._get_min_qty(symbol)
        min_qty_val = min_qty if min_qty else (getattr(self.service, 'min_qty', {}).get(symbol, 0.0001) if self.service and hasattr(self.service, 'min_qty') else 0.0001)
        pos_min_qty = max(self.config.MIN_POSITION_SIZE / current_price, min_qty_val )
        entry_price = getattr(position, "entry_price", current_price); position_value = positionAmt * current_price
        position_gain = getattr(position, "gain", 0.0); last_aug_amt = getattr(position, "last_augmentation_amount", 0.0) or getattr(position, "last_augmentation_qty", 0.0)
        last_aug_price = getattr(position, "last_augmentation_price", None) or entry_price
        dc_low4 = indicators.get("dc_low_3m", current_price); dc_high4 = indicators.get("dc_high_3m", current_price)
        atr_3m = indicators.get("atr_3m", 0.0); level1 = dc_low4 if is_long else dc_high4
        min_distance = self._calculate_min_stop_distance(entry_price, indicators, is_long, current_price, position_gain)
        initial_min_distance = self._initial_min_distance.get(position_key)
        if initial_min_distance is None and min_distance > 0:
            self._initial_min_distance[position_key] = min_distance
            initial_min_distance = min_distance
        existing_levels = self.stop_levels.get(position_key, [])
        existing_stop_price = None
        if existing_levels and len(existing_levels) > 0:
            first_level = existing_levels[0]
            if isinstance(first_level, dict):
                existing_stop_price = float(first_level.get("level", 0.0) or 0.0)
            elif hasattr(first_level, "level"):
                existing_stop_price = float(getattr(first_level, "level", 0.0) or 0.0)
        # TEMPORARILY COMMENTED OUT: Breakeven logic when price moves 1 ATR_3M
       # price_moved_atr = (is_long and current_price >= entry_price + atr_3m) or (not is_long and current_price <= entry_price - atr_3m)
        price_moved_atr = False  # Temporarily disabled

        # Stricter break-even: use entry_price or augment_price +/- 0.015% (commissions)
        breakeven_base = last_aug_price if last_aug_amt > 0 and last_aug_price > 0 else entry_price
        breakeven_stop = breakeven_base * 1.0015 if is_long else breakeven_base * 0.9985
        position_value_usd = positionAmt * current_price
        if position_value_usd > 500: num_steps = 3
        elif position_value_usd >= 200: num_steps = 2
        else: num_steps = 1
        reductions = self._compute_reduction_amounts(positionAmt=positionAmt, position_value=position_value_usd, pos_min_qty=pos_min_qty, current_price=current_price, num_steps=num_steps, last_aug_qty=last_aug_amt)
        levels = []
        if last_aug_amt > 0 and position_gain > 0.3:
            if len(reductions) > 0: reductions[0] = last_aug_amt
            aug_level_price = entry_price * (1.01 if is_long else 0.99)
            aug_level_price = self._enforce_min_distance(aug_level_price, entry_price, min_distance, is_long, initial_min_distance, existing_stop_price, dc_low4, dc_high4, current_price, atr_3m)
            levels.append(StopLevel(level=aug_level_price, reduction_amount=reductions[0] if len(reductions) > 0 else last_aug_amt, position_side=position_side, strategy="augmentation", created_at=now_ts, updated_at=now_ts))
            if len(reductions) >= 2:
                level2 = entry_price
                level2 = self._enforce_min_distance(level2, entry_price, min_distance, is_long, initial_min_distance, existing_stop_price, dc_low4, dc_high4, current_price, atr_3m)
                levels.append(StopLevel(level=level2, reduction_amount=reductions[1] if len(reductions) > 1 else positionAmt-pos_min_qty, position_side=position_side, strategy="breakeven", created_at=now_ts, updated_at=now_ts))
                if len(reductions) >= 3:
                    level3 = level2 * (0.995 if is_long else 1.005)
                    level3 = self._enforce_min_distance(level3, entry_price, min_distance, is_long, initial_min_distance, existing_stop_price, dc_low4, dc_high4, current_price, atr_3m)
                    levels.append(StopLevel(level=level3, reduction_amount=reductions[2], position_side=position_side, strategy="tier3", created_at=now_ts, updated_at=now_ts))
        else:
            # TEMPORARILY COMMENTED OUT: Breakeven stop when price moves 1 ATR_3M
            # if price_moved_atr and len(reductions) > 0:
            #     levels.append(StopLevel(level=breakeven_stop, reduction_amount=reductions[0], position_side=position_side, strategy="breakeven_atr_strict", created_at=now_ts, updated_at=now_ts, breakeven_applied=True))
            # # Also enforce break-even as first level if price moved ATR but no reductions yet
            # elif price_moved_atr and len(reductions) == 0 and positionAmt > pos_min_qty:
            #     emergency_reduction = max(positionAmt - pos_min_qty, 0.0)
            #     if emergency_reduction > 0:
            #         levels.append(StopLevel(level=breakeven_stop, reduction_amount=emergency_reduction, position_side=position_side, strategy="breakeven_atr_strict", created_at=now_ts, updated_at=now_ts, breakeven_applied=True))
            level2 = max(level1 * 0.995, dc_low4) if is_long else min(level1 * 1.005, dc_high4); level3 = level2 * (0.995 if is_long else 1.005)
            level1 = self._enforce_min_distance(level1, entry_price, min_distance, is_long, initial_min_distance, existing_stop_price, dc_low4, dc_high4, current_price, atr_3m)
            level2 = self._enforce_min_distance(level2, entry_price, min_distance, is_long, initial_min_distance, existing_stop_price, dc_low4, dc_high4, current_price, atr_3m)
            level3 = self._enforce_min_distance(level3, entry_price, min_distance, is_long, initial_min_distance, existing_stop_price, dc_low4, dc_high4, current_price, atr_3m)
            price_levels = [level1, level2, level3] if not price_moved_atr else [level1, level3]
            for i, (price, reduction) in enumerate(zip(price_levels, reductions[1:] if price_moved_atr else reductions)):
                if i < num_steps and reduction > 0:
                    levels.append(StopLevel(level=price, reduction_amount=reduction, position_side=position_side, strategy=f"tier{i+1}", created_at=now_ts, updated_at=now_ts))
        levels = levels[:num_steps]
        if not levels:
            emergency_base = current_price * (0.99 if is_long else 1.01)
            # Ensure emergency stop is NOT closer than the enforced baseline
            emergency_price = min(level1, emergency_base) if is_long else max(level1, emergency_base)
            emergency_price = self._enforce_min_distance(emergency_price, entry_price, min_distance, is_long, initial_min_distance, existing_stop_price, dc_low4, dc_high4, current_price, atr_3m)
            emergency_reduction = max(positionAmt - pos_min_qty, 0.0)
            if emergency_reduction > 0 and not (config.HEDGE_MODE and position_gain < 0.12):
                levels.append(StopLevel(level=emergency_price, reduction_amount=emergency_reduction, position_side=position_side, strategy="emergency", created_at=now_ts, updated_at=now_ts))
        primary_price = level1
        if primary_price <= 0.0:
            logger.error(f"[{position_key}] Missing dc_low4_3m/dc_high4_3m indicator (is_long={is_long}) current_price={current_price:.6f}")
            primary_price = current_price
        primary_price = self._enforce_min_distance(primary_price, entry_price, min_distance, is_long, initial_min_distance, existing_stop_price, dc_low4, dc_high4, current_price, atr_3m)
        if primary_price > 0.0 and positionAmt > 0.0:
            max_reduction = max(0.0, positionAmt - pos_min_qty)
            baseline_reduction = reductions[0] if reductions else 0.0
            prev_gain_check_valid_stop = False
            prev_gain_stop = 0.0
            if position and hasattr(position, 'prev_gain_last_updated') and position.prev_gain_last_updated:
                age_seconds = (datetime.now(timezone.utc) - position.prev_gain_last_updated).total_seconds()
                if age_seconds < 480.0:
                    prev_gain_stop = safe_fetch_float(getattr(position, "prev_gain", 0.0), 0.0)
                    # Skip comparison if gain was reset to 0 (position reduced)
                    if position_gain != 0.0 or prev_gain_stop != 0.0:
                        prev_gain_check_valid_stop = True
            if not prev_gain_check_valid_stop:
                indicator_price_stop = safe_fetch_float(indicators.get('current_price', 0), current_price)
                if indicator_price_stop and indicator_price_stop > 0:
                    price_deteriorated_stop = (is_long and current_price < indicator_price_stop) or (not is_long and current_price > indicator_price_stop)
                else:
                    price_deteriorated_stop = False  # No valid prev_gain, skip comparison
            else:
                price_deteriorated_stop = position_gain < prev_gain_stop
            loss_reduce = position_gain < 0.3 and price_deteriorated_stop
            primary_reduction = max_reduction if max_reduction > 0.0 else baseline_reduction
            primary_reduction = min(primary_reduction, max_reduction)
            if primary_reduction > 0.0:
                primary_level = StopLevel(level=primary_price, reduction_amount=primary_reduction, position_side=position_side, strategy="dc4_primary_loss_guard" if loss_reduce else "dc4_primary", created_at=now_ts, updated_at=now_ts)
                remaining = max(0.0, max_reduction - primary_reduction)
                dedup_levels = []
                for lvl in levels:
                    try:
                        if isinstance(lvl, dict):
                            lvl_price = float(lvl.get("level", 0.0)); lvl_amount = float(lvl.get("reduction_amount", 0.0)); lvl_strategy = str(lvl.get("strategy", "tier")); raw_created = lvl.get("created_at", now_ts)
                            if isinstance(raw_created, str):
                                try: lvl_created = ensure_tz(isoparse(raw_created))
                                except Exception: lvl_created = now_ts
                            elif isinstance(raw_created, datetime): lvl_created = ensure_tz(raw_created)
                            else: lvl_created = now_ts
                        else:
                            lvl_price = float(getattr(lvl, "level", 0.0)); lvl_amount = float(getattr(lvl, "reduction_amount", 0.0)); lvl_strategy = getattr(lvl, "strategy", "tier"); lvl_created = ensure_tz(getattr(lvl, "created_at", now_ts))
                    except Exception:
                        lvl_price = 0.0; lvl_amount = 0.0; lvl_strategy = "tier"; lvl_created = now_ts
                    if abs(lvl_price - primary_price) <= max(primary_price * 1e-6, 1e-9):
                        continue
                    if remaining <= 0.0 or lvl_amount <= 0.0:
                        continue
                    adj_amt = min(lvl_amount, remaining)
                    if adj_amt <= 0.0:
                        continue
                    lvl_price = self._enforce_min_distance(lvl_price, entry_price, min_distance, is_long, initial_min_distance, existing_stop_price, dc_low4, dc_high4, current_price, atr_3m)
                    dedup_levels.append(StopLevel(level=lvl_price, reduction_amount=adj_amt, position_side=position_side, strategy=lvl_strategy, created_at=lvl_created, updated_at=now_ts))
                    remaining -= adj_amt
                levels = [primary_level] + dedup_levels
            levels = levels[:num_steps] if num_steps > 0 else levels
        return levels

    def _compute_reduction_amounts(self,*,positionAmt:float,position_value:float,pos_min_qty:float,current_price:float,last_aug_qty:float=0.0,num_steps:int=3) -> List[float]:
        if positionAmt <= pos_min_qty or current_price <= 0.0: return []
        running = positionAmt; reductions = []
        if last_aug_qty > 0.0:
            aug_reduction = min(last_aug_qty, running - pos_min_qty)
            if aug_reduction > 0: reductions.append(aug_reduction); running -= aug_reduction
        remaining_steps = num_steps - len(reductions)
        if remaining_steps > 0 and running > pos_min_qty:
            if remaining_steps == 1: reductions.append(running - pos_min_qty)
            else:
                step_size = (running - pos_min_qty) / remaining_steps
                for i in range(remaining_steps):
                    if i == remaining_steps - 1: reductions.append(running - pos_min_qty)
                    else:
                        reduction = min(step_size, running - pos_min_qty)
                        if reduction > 0: reductions.append(reduction); running -= reduction
        reductions = [r for r in reductions if r > 0]
        return reductions[:num_steps]

    def select_binance_stop(self,*,levels:List[StopLevel],position_key:str,position_side:str,current_price:float,positionAmt:float,pos_min_qty:float,indicators:Dict[str,Any]=None) -> Optional[StopLevel]:
        if not levels: return None
        tier1 = levels[0]; is_long = position_side.upper() == "LONG"
        if isinstance(tier1, StopLevel):
            strategy = tier1.strategy; tier1_level = float(getattr(tier1, "level", 0.0)); tier1_reduction = float(getattr(tier1, "reduction_amount", 0.0))
            try: tier1_created_at = ensure_tz(getattr(tier1, "created_at", datetime.now(timezone.utc)))
            except Exception: tier1_created_at = datetime.now(timezone.utc)
        else:
            strategy = str(tier1.get("strategy", "")); tier1_level = float(tier1.get("level", 0.0)); tier1_reduction = float(tier1.get("reduction_amount", 0.0)); raw_created = tier1.get("created_at")
            if isinstance(raw_created, datetime): tier1_created_at = ensure_tz(raw_created)
            elif raw_created:
                try: tier1_created_at = ensure_tz(isoparse(str(raw_created)))
                except Exception: tier1_created_at = datetime.now(timezone.utc)
            else: tier1_created_at = datetime.now(timezone.utc)
        dc_low_3m = float(indicators.get("dc_low_3m", 0.0) or 0.0) if indicators else 0.0
        dc_high_3m = float(indicators.get("dc_high_3m", 0.0) or 0.0) if indicators else 0.0
        stop_level = dc_low_3m if (is_long and dc_low_3m > 0.0) else (dc_high_3m if (not is_long and dc_high_3m > 0.0) else 0.0)
        if stop_level <= 0.0: stop_level = tier1_level
        reduction_qty = max(0.0, min(tier1_reduction, positionAmt - pos_min_qty)) if strategy in ("dc4_primary","dc4_primary_loss_guard") else max(0.0, positionAmt - pos_min_qty)
        if reduction_qty <= 0.0 or (positionAmt > 0 and reduction_qty / positionAmt < 0.12):
            return None
        return StopLevel(level=stop_level, reduction_amount=reduction_qty, position_side=position_side, strategy="dc4_exchange", created_at=tier1_created_at if isinstance(tier1_created_at, datetime) else datetime.now(timezone.utc), updated_at=datetime.now(timezone.utc))

    async def _validate_existing_levels(self, existing_levels, position_key, position_side, current_price):
        validated = []; is_long = position_side.upper() == "LONG"
        for level in existing_levels:
            if isinstance(level, dict): stop_price = level.get('level', 0); strategy = level.get('strategy', '')
            else: stop_price = getattr(level, 'level', 0); strategy = getattr(level, 'strategy', '')
            price_diff_pct = abs(stop_price - current_price) / current_price
            if price_diff_pct < 0.1: validated.append(level)
        return validated
        
    async def _sync_with_exchange(self,*,account_key:str,symbol:str,position_key:str,position_side:str,open_orders:List[Dict[str,Any]],desired_levels:List[StopLevel],current_price:float,positionAmt:float,pos_min_qty:float) -> None:
        if config.HEDGE_MODE:return
        now = time.time()
        last_update = self._recent_stop_updates.get(position_key, 0)
        if now - last_update < 5.0:
            logger.debug(f"[{position_key}] Stop order placement throttled (last update {now - last_update:.1f}s ago)")
            return
        existing_levels = self.stop_levels.get(position_key, [])
        tiny_threshold = pos_min_qty * 1.2
        if not desired_levels: self.stop_levels.pop(position_key, None)
        should_preserve = (existing_levels and len(existing_levels) > 0 and any((level.get('strategy') if isinstance(level, dict) else getattr(level, 'strategy', '')) in ['breakeven', 'tier2', 'tier3'] for level in existing_levels))
        if should_preserve:
            validated_levels = await self._validate_existing_levels(existing_levels, position_key, position_side, current_price)
            if validated_levels: desired_levels = validated_levels
        client=self._get_client(account_key)
        open_orders = open_orders or []
        all_stop_orders = [o for o in open_orders if o.get('type') in ['STOP_MARKET', 'STOP', 'TAKE_PROFIT_MARKET', 'TAKE_PROFIT'] and o.get('positionSide') == position_side]
        managed_orders = [o for o in all_stop_orders if self._is_managed_stop(o, position_key)]
        external_orders = [o for o in all_stop_orders if o not in managed_orders]
        if len(all_stop_orders) > 0:
            logger.warning(f"[{position_key}] CRITICAL: Found {len(all_stop_orders)} stop orders - cancelling ALL before creating ONE new order")
            for order in all_stop_orders:
                order_id = str(order.get("orderId") or "")
                if order_id:
                    try:
                        await self._rate_limited_api_call(asyncio.to_thread(client.futures_cancel_order, symbol=symbol, orderId=order_id))
                        logger.warning(f"[{position_key}] Cancelled existing stop order {order_id}")
                    except Exception as exc:
                        logger.warning(f"[{position_key}] Failed to cancel order {order_id}: {exc}")
            await asyncio.sleep(0.2)
        if (not desired_levels) or positionAmt < tiny_threshold or current_price <= 0.0:
            if client:
                for order in managed_orders:
                    order_id=str(order.get("orderId") or "")
                    if not order_id: continue
                    try:
                        await self._rate_limited_api_call(asyncio.to_thread(client.futures_cancel_order,symbol=symbol,orderId=order_id))
                    except Exception as exc:
                        logger.warning(f"[{position_key}] cancel tiny stop failed {exc}")
                    self._managed_stop_ids.discard(order_id); self._clear_stop(position_key,order_id)
            if managed_orders: await self._schedule_registry_flush()
            if positionAmt < 1.5 * pos_min_qty:
                self.stop_levels.pop(position_key, None)
            if positionAmt < pos_min_qty and self.service and hasattr(self.service, 'cancel_empty_stop'):
                try:
                    await self.service.cancel_empty_stop(account_key,symbol,position_key,current_price,positionAmt,require_tiny=True)
                except Exception as exc:
                    logger.warning(f"[{position_key}] cancel_empty_stop tiny failed: {exc}")
            return
        position = self.service.positions.get(position_key) if self.service else None
        if position:
            fetched_amt = abs(safe_fetch_float(position.positionAmt))
            if abs(fetched_amt - positionAmt) > max(positionAmt * 0.01, 1e-9):
                logger.warning(f"[{position_key}] positionAmt mismatch: passed={positionAmt:.6f} binance={fetched_amt:.6f}")
                positionAmt = fetched_amt
        if external_orders and not managed_orders:
            logger.debug(f"[{position_key}] External stop detected, skipping bot-managed stop sync (position will still be updated)")
            return
        if positionAmt < pos_min_qty and self.service and hasattr(self.service, 'cancel_empty_stop'):
            try:
                await self.service.cancel_empty_stop(account_key, symbol, position_key, current_price, positionAmt, require_tiny=True)
                return
            except Exception as exc:
                logger.warning(f"[{position_key}] cancel_empty _stop failed: {exc}")
        desired = desired_levels[0]
        indicators = self._get_indicators(symbol) if self._get_indicators and not asyncio.iscoroutinefunction(self._get_indicators) else {}
        if asyncio.iscoroutinefunction(self._get_indicators) and self._get_indicators:
            indicators = await self._get_indicators(symbol)
        binance_level = self.select_binance_stop(levels=desired_levels, position_key=position_key, position_side=position_side, current_price=current_price, positionAmt=positionAmt, pos_min_qty=pos_min_qty, indicators=indicators)
        if not binance_level:
            for order in managed_orders:
                order_id = str(order.get("orderId") or "")
                try:
                    await self._rate_limited_api_call(asyncio.to_thread(client.futures_cancel_order, symbol=symbol, orderId=order_id))
                except Exception as exc:
                    logger.warning(f"[{position_key}] cancel failed (insufficient reduction) {exc}")
                self._managed_stop_ids.discard(order_id)
                self._clear_stop(position_key, order_id)
            await self._schedule_registry_flush()
            self.stop_levels.pop(position_key, None)
            return
        candidate_price = binance_level.level if binance_level else None
        last_entry = None
        if self.service and hasattr(self.service, "managed_stop_registry"):
            last_entry = self.service.managed_stop_registry.get(position_key)
        now = time.time()
        symbol_cfg = self.get_symbol_config(symbol) or {}
        tick_size = safe_float(symbol_cfg.get("tick_size") or symbol_cfg.get("tickSize") or 0.0)
        def normalize_num(value):
            if isinstance(value, str):
                try:
                    return float(value.strip())
                except ValueError:
                    return None
            if isinstance(value, (int, float)):
                return float(value)
            return None
        tick_size = normalize_num(symbol_cfg.get("tick_size") or symbol_cfg.get("tickSize") or 0.0)
        step_size = normalize_num(symbol_cfg.get("step_size") or symbol_cfg.get("stepSize") or 0.0)
        is_long = position_side.upper() == "LONG"
        def clamp_price(raw: float) -> Tuple[float, int]:
            if not tick_size:
                return raw, 8
            precision = max(0, int(-math.log10(tick_size)))
            snapped = math.floor(raw / tick_size) * tick_size if is_long else math.ceil(raw / tick_size) * tick_size
            snapped = float(Decimal(snapped).quantize(Decimal(str(tick_size))))
            return snapped, precision
        def clamp_qty(raw: float) -> Tuple[float, str]:
            target = raw
            if current_price > 0 and target * current_price < 5.0:
                target = 5.0 / current_price
            if step_size:
                precision = max(0, int(-math.log10(step_size)))
                snapped = math.floor(target / step_size) * step_size
                if snapped <= 0.0:
                    snapped = step_size
                snapped = float(Decimal(snapped).quantize(Decimal(str(step_size))))
                snapped = min(snapped, positionAmt)
                return snapped, f"{snapped:.{precision}f}".rstrip("0").rstrip(".")
            qty = float(Decimal(target).quantize(Decimal("0.00000001")))
            return qty, f"{qty:.8f}".rstrip("0").rstrip(".")
        price_float, price_precision = clamp_price(binance_level.level)
        entry_price = getattr(position, "entry_price", current_price) if position else current_price
        position_gain = getattr(position, "gain", 0.0) if position else 0.0
        indicators = self.get_indicators(symbol) if hasattr(self, 'get_indicators') and self.get_indicators else {}
        atr_3m = float(indicators.get("atr_3m", 0.0) or 0.0) if indicators else 0.0
        dc_low_3m = float(indicators.get("dc_low_3m", 0.0) or 0.0) if indicators else 0.0
        dc_high_3m = float(indicators.get("dc_high_3m", 0.0) or 0.0) if indicators else 0.0
        price_moved_3atr = (is_long and current_price >= entry_price + 3 * atr_3m) or (not is_long and current_price <= entry_price - 3 * atr_3m) if (atr_3m > 0 and entry_price > 0 and current_price > 0) else False
        if entry_price > 0 and current_price > 0:
            if not price_moved_3atr:
                if dc_low_3m > 0 and is_long and price_float < dc_low_3m:
                    logger.warning(f"[{position_key}] Stop price {price_float:.{price_precision}f} closer than dc_low_3m {dc_low_3m:.{price_precision}f} (price not moved 3*atr_3m={3*atr_3m:.6f} yet), enforcing minimum")
                    price_float = dc_low_3m
                    price_float, price_precision = clamp_price(price_float)
                elif dc_high_3m > 0 and not is_long and price_float > dc_high_3m:
                    logger.warning(f"[{position_key}] Stop price {price_float:.{price_precision}f} closer than dc_high_3m {dc_high_3m:.{price_precision}f} (price not moved 3*atr_3m={3*atr_3m:.6f} yet), enforcing minimum")
                    price_float = dc_high_3m
                    price_float, price_precision = clamp_price(price_float)
            else:
                min_allowed_distance_pct = 0.003
                if is_long:
                    min_allowed_price = entry_price * (1 - min_allowed_distance_pct)
                    if price_float < min_allowed_price:
                        logger.warning(f"[{position_key}] Stop price {price_float:.{price_precision}f} too close to entry {entry_price:.6f} (<0.3%), adjusting to {min_allowed_price:.{price_precision}f}")
                        price_float = min_allowed_price
                        price_float, price_precision = clamp_price(price_float)
                else:
                    max_allowed_price = entry_price * (1 + min_allowed_distance_pct)
                    if price_float > max_allowed_price:
                        logger.warning(f"[{position_key}] Stop price {price_float:.{price_precision}f} too close to entry {entry_price:.6f} (<0.3%), adjusting to {max_allowed_price:.{price_precision}f}")
                        price_float = max_allowed_price
                        price_float, price_precision = clamp_price(price_float)
        existing_stop_price = None
        if managed_orders and len(managed_orders) > 0:
            existing_stop_price = safe_float(managed_orders[0].get("stopPrice"))
        if existing_stop_price and existing_stop_price > 0 and current_price > 0:
            price_diff_pct = abs(price_float - existing_stop_price) / current_price
            if price_diff_pct <= 0.0025:
                logger.debug(f"[{position_key}] Stop price change {price_diff_pct*100:.4f}% <= 0.25%, skipping Binance update (current={existing_stop_price:.{price_precision}f}, new={price_float:.{price_precision}f})")
                return
        qty_float, qty_str = clamp_qty(binance_level.reduction_amount)
        min_reduction_to_min_qty = max(0.0, positionAmt - pos_min_qty)
        if min_reduction_to_min_qty > 0 and qty_float > min_reduction_to_min_qty:
            qty_float, qty_str = clamp_qty(min_reduction_to_min_qty)
            logger.debug(f"[{position_key}] Adjusted stop qty to respect pos_min_qty: {qty_float:.6f} (max allowed: {min_reduction_to_min_qty:.6f}, positionAmt: {positionAmt:.6f}, pos_min_qty: {pos_min_qty:.6f})")
        if qty_float <= 0.0:
            logger.warning(f"[{position_key}] computed zero qty after clamp, skip")
            await self._cancel_all_managed_stops(client,symbol,managed_orders,position_key)
            return
        if all_stop_orders:
            for existing_order in all_stop_orders:
                order_id = str(existing_order.get("orderId") or "")
                if not order_id:
                    continue
                try:
                    await self._rate_limited_api_call(asyncio.to_thread(client.futures_cancel_order, symbol=symbol, orderId=order_id))
                    logger.info(f"[{position_key}] Cancelled existing stop order {order_id} before creating new one")
                except BinanceAPIException as exc:
                    if exc.code in (-2011, -2013):
                        logger.debug(f"[{position_key}] cancel skipped: order already gone ({exc.code})")
                    else:
                        logger.warning(f"[{position_key}] cancel existing stop failed {exc}")
                except Exception as exc:
                    logger.warning(f"[{position_key}] cancel existing stop failed {exc}")
                self._managed_stop_ids.discard(order_id)
                self._clear_stop(position_key, order_id)
            await self._schedule_registry_flush()
            await asyncio.sleep(0.1)
        # We calculate the stops logic but DO NOT send them to Binance.
        # This prevents the "Death by 1000 cuts" from stop orders triggering on wicks.
        # The bot will now rely solely on internal monitoring (_enforce_stop_reduction).
        
        self._managed_stop_ids.add("VIRTUAL_STOP") # Fake ID to satisfy internal logic
        binance_level.order_id = "VIRTUAL_STOP"
        binance_level.binance_stop_price = price_float
        binance_level.managed_on_exchange = False # Mark as NOT on exchange
        
        # Log that we calculated it but didn't place it
        if config.VERBOSE_STOPS: 
            logger.info(f"[{position_key}] VIRTUAL Stop calculated qty={qty_str} @ {price_float:.{price_precision}f} (Not sent to Binance)")
            
        return # EXIT FUNCTION HERE TO PREVENT API CALL
        
    async def _rate_limited_api_call(self, coro):
        if self._ban_detected:
            if time.time() - self._ban_start_time < 300:  # 5 minute cooldown
                logger.warning("⏸️ API ban detected - skipping call")
                raise Exception("API temporarily banned")
            else:
                self._ban_detected = False
        self._check_rate_limit()
        async with self._rate_limit_semaphore:
            now = time.time()
            time_since_last = now - self._last_api_call
            if time_since_last < self._api_call_interval:
                await asyncio.sleep(self._api_call_interval - time_since_last)
            try:
                result = await coro
                self._last_api_call = time.time()
                if self._ban_detected:
                    self._ban_detected = False
                return result
            except Exception as e:
                if "Too many requests" in str(e) or "ban" in str(e).lower():
                    self._ban_detected = True
                    self._ban_start_time = time.time()
                    logger.error("🚨 API BAN DETECTED - pausing API calls for 5 minutes")
                    if isinstance(e, BinanceAPIException) and hasattr(self, "accounts"):
                        ctx_account = current_account.get()
                        targets = [ctx_account] if ctx_account and ctx_account in self.accounts else list(self.accounts.keys())
                        for key in targets:
                            account = self.accounts.get(key)
                            if not account or not hasattr(account, "handle_api_ban"):
                                continue
                            account.handle_api_ban(cooldown_seconds=900)
                raise e   
    def _check_rate_limit(self):
        now = time.time()
        self._api_call_times = [t for t in self._api_call_times if now - t < 60]
        if len(self._api_call_times) >= self.max_api_calls_per_minute * 0.8:  # 80% of limit
            logger.warning("⚠️ Approaching API rate limit - slowing down")
            time.sleep(1.0)
        self._api_call_times.append(now)

    def get_stop_file(self, account_key: str, side: str) -> Path:
        base_path = Path(config.BASE_PATH)
        account_dir = base_path / account_key
        account_dir.mkdir(exist_ok=True)
        file_path = account_dir / f"{side.lower()}_stop_levels.json"
        if not file_path.exists():
            file_path.touch()
        return file_path
        
    async def stop_json_repair_from_backup(self, corrupted_file_path: str, account_key: str, side: str) -> dict:
        try:
            backup_dir = Path(f"./{account_key}/backups")
            if not backup_dir.exists():
                logger.warning(f"[REPAIR] No backup directory found for {account_key}")
                return {}
            backup_pattern = f"{side.lower()}_stop_levels.json_backup_*.json"
            backup_files = list(backup_dir.glob(backup_pattern))
            if not backup_files:
                logger.warning(f"[REPAIR] {account_key}: No backup files found for {side.lower()}_stop_levels.json")
                return {}
            backup_files.sort(key=lambda p: p.stat().st_mtime, reverse=True)
            for backup_file in backup_files:
                try:
                    async with LimitedAioOpen(backup_file, 'r') as f:
                        content = await f.read()
                        if content.strip():
                            backup_data = json.loads(content)
                            if isinstance(backup_data, dict):
                                cleaned_data = {}
                                for key, value_dict in backup_data.items():
                                    if isinstance(value_dict, dict) and "stop_levels" in value_dict:
                                        stop_levels = value_dict["stop_levels"]
                                        if isinstance(stop_levels, list):
                                            clean_stop_levels = []
                                            for stop_obj in stop_levels:
                                                if isinstance(stop_obj, dict) and "level" in stop_obj:
                                                    clean_stop_obj = {
                                                        "level": float(stop_obj.get("level", 0.0)),
                                                        "reduction_amount": float(stop_obj.get("reduction_amount", 0.0)),
                                                        "augmentation_price": float(stop_obj.get("augmentation_price", 0.0)),
                                                        "created_at": str(stop_obj.get("created_at", "")),
                                                        "position_side": str(stop_obj.get("position_side", ""))
                                                    }
                                                    clean_stop_levels.append(clean_stop_obj)
                                            if clean_stop_levels:
                                                cleaned_data[key] = {
                                                    "stop_levels": clean_stop_levels,
                                                    "last_updated": value_dict.get("last_updated", "")
                                                }
                                return cleaned_data
                except (json.JSONDecodeError, Exception) as e:
                    logger.debug(f"[REPAIR] Backup file {backup_file} also corrupted: {e}")
                    continue
            logger.warning(f"[REPAIR] All backup files for {side.lower()}_stop_levels.json are corrupted")
            return {}
        except Exception as e:
            logger.error(f"[REPAIR] Failed to repair multi stop levels JSON: {e}")
            return {}

    async def _attempt_json_repair(self, content: str) -> str:
        """Attempt to repair common JSON issues"""
        try:
            content = content.lstrip('\ufeff')
            import re
            content = re.sub(r',(\s*[}\]])', r'\1', content)
            content = re.sub(r'}(\s*){', r'},', content)
            return content
        except Exception:
            return None

    async def cleanup_empty_stop_levels(self):
        for account_key, account in self.accounts.items():
            client = getattr(account,"client",None)
            if not client: continue
            try:
                open_orders = await self.get_cached_open_orders(client)
            except Exception as exc:
                logger.error(f"[{account_key}] cleanup stops failed to fetch orders: {exc}")
                continue
            account_positions = self.positions_by_account.get(account_key,{})
            for order in open_orders:
                if order.get("type") != "STOP_MARKET": continue
                order_id = str(order.get("orderId") or "")
                symbol = order.get("symbol") or ""
                pos_side = order.get("positionSide") or ""
                if not order_id or not symbol or not pos_side: continue
                position_key = construct_position_key(account_key, symbol, pos_side)
                position = account_positions.get(position_key)
                mark_price_val = safe_fetch_float(getattr(position,"mark_price",0), 0.0) if position else 0.0
                notional = (getattr(position,"positionAmt",0) or 0) * mark_price_val
                if position and notional > max(self.config.MIN_POSITION_SIZE, self.stop_manager._get_min_qty(symbol) * mark_price_val):
                    continue
                try:
                    await asyncio.to_thread(client.futures_cancel_order, symbol=symbol, orderId=order_id)
                    self.stop_manager._managed_stop_ids.discard(order_id)
                    self.stop_manager._clear_stop(position_key, order_id)
                except Exception as exc:
                    logger.warning(f"[{position_key}] cleanup stop cancel failed for {order_id}: {exc}")
        await self.stop_manager._flush_registry()  

    async def stop_levels_save(self, account_key: str, force: bool = False, min_interval: int = 60):
        if not account_key or not isinstance(account_key, str): return
        now_ts = time.time()
        if not hasattr(self, "_last_stop_levels_save_time"):
            self._last_stop_levels_save_time: Dict[str, float] = {}
        if not force and account_key in self._last_stop_levels_save_time:
            last_save_ts = self._last_stop_levels_save_time[account_key]
            if (now_ts - last_save_ts) < min_interval:
                return
        now = datetime.now(timezone.utc)
        for side in ['LONG', 'SHORT']:
            file_path = self.get_stop_file(account_key, side)
            existing_data = {}
            try:
                if await aio_os.path.exists(file_path):
                    async with LimitedAioOpen(file_path, 'r') as f:
                        content = await f.read()
                        if content.strip(): existing_data = json.loads(content)
            except json.JSONDecodeError: existing_data = await self.stop_json_repair_from_backup(file_path, account_key, side)
            except Exception: existing_data = {}
            if not isinstance(existing_data, dict): existing_data = {}
            current_side_keys = set()
            stop_levels_store = self.stop_manager.stop_levels if self.stop_manager else {}
            
            for position_key, stop_levels in stop_levels_store.items():
                if position_key.count(":") == 1 and position_key.count("_") >= 1:
                    try:
                        acc, symbol_side = position_key.split(":", 1)
                        symbol, key_side = symbol_side.rsplit("_", 1)
                        if acc == account_key and key_side == side:
                            if not stop_levels or len(stop_levels) == 0: continue
                            stop_levels = list(stop_levels)[:2]
                            serialized_stop_levels = []
                            for stop_obj in stop_levels:
                                if hasattr(stop_obj, 'level'):
                                    clean_stop_obj = {"level": float(stop_obj.level), "reduction_amount": float(stop_obj.reduction_amount), "augmentation_price": float(getattr(stop_obj, 'augmentation_price', 0.0)), "created_at": str(stop_obj.created_at), "position_side": str(stop_obj.position_side)}
                                    serialized_stop_levels.append(clean_stop_obj)
                                elif isinstance(stop_obj, dict):
                                    clean_stop_obj = {"level": float(stop_obj.get("level", 0.0)), "reduction_amount": float(stop_obj.get("reduction_amount", 0.0)), "augmentation_price": float(stop_obj.get("augmentation_price", 0.0)), "created_at": str(stop_obj.get("created_at", "")), "position_side": str(stop_obj.get("position_side", ""))}
                                    serialized_stop_levels.append(clean_stop_obj)
                            if serialized_stop_levels:
                                existing_data[position_key] = {"stop_levels": serialized_stop_levels, "last_updated": now.strftime('%Y-%m-%dT%H:%M:%S.%fZ')}
                                current_side_keys.add(position_key)
                    except (ValueError, TypeError, KeyError) as e: logger.error(f"Error processing stop levels for {position_key}: {e}")
            stop_levels_store = self.stop_manager.stop_levels if self.stop_manager else {}
            memory_count = sum(1 for k in stop_levels_store.keys() if k.startswith(f"{account_key}:") and k.endswith(f"_{side}"))
            if getattr(self.config, 'VERBOSE_FETCH_LOGGING', getattr(self.config, 'VERBOSE', False)):
                if config.VERBOSE_STOPS: logger.info(f"[stop_levels_save] {account_key}:{side}: memory_data={memory_count} entries, existing_data={len(existing_data)} entries: {list(existing_data.keys())[:10]}")
            try:
                await ensure_path_writable(file_path)
                json_str = json.dumps(existing_data, indent=2)
                json_str_bytes = len(json_str.encode('utf-8'))
                async with LimitedAioOpen(file_path, 'w') as f:
                    await f.write(json_str)
                    await f.flush()
                final_size = file_path.stat().st_size if file_path.exists() else 0
                if final_size != json_str_bytes:
                    logger.error(f"[stop_levels_save] File size mismatch for {file_path}: expected {json_str_bytes} bytes, got {final_size} bytes")
                await self._broadcast_stop_levels_to_redis(account_key, side, existing_data)
                #logger.info(f"[stop_levels_save] Saved {len(current_side_keys)} stops for {account_key} {side}")
            except Exception as e: logger.error(f"Error saving stop levels to {file_path}: {e}")
        self._last_stop_levels_save_time[account_key] = now_ts

    async def load_stop_levels(self, account_key: str):
        if not account_key or not isinstance(account_key, str): return
        loaded_count = 0
        for position_side in ['LONG', 'SHORT']:
            file_path = self.get_stop_file(account_key, position_side)
            stop_data = {}
            try:
                if await aio_os.path.exists(file_path):
                    async with LimitedAioOpen(file_path, 'r') as f:
                        content = await f.read()
                        if content.strip(): stop_data = json.loads(content)
            except json.JSONDecodeError: stop_data = await self.stop_json_repair_from_backup(file_path, account_key, position_side)
            except Exception: stop_data = {}
            if isinstance(stop_data, dict):
                for key, value_dict in stop_data.items():
                    if not (key.count(":") == 1 and key.count("_") >= 1 and key.startswith(f"{account_key}:") and key.endswith(f"_{position_side}")): continue
                    if isinstance(value_dict, dict) and "stop_levels" in value_dict:
                        stop_levels = value_dict["stop_levels"]
                        if isinstance(stop_levels, list):
                            clean_stop_levels = []
                            for stop_obj in stop_levels:
                                try:
                                    if isinstance(stop_obj, StopLevel):
                                        clean_stop_levels.append(stop_obj)
                                    elif isinstance(stop_obj, dict) and "level" in stop_obj:
                                        clean_stop_levels.append(StopLevel.from_dict(stop_obj))
                                except Exception:
                                    continue
                            if clean_stop_levels:
                                clean_stop_levels = clean_stop_levels[:2]
                                self.stop_levels[key] = clean_stop_levels
                                loaded_count += 1
        logger.debug(f"[load_stop_levels] Loaded {loaded_count} stops for {account_key}")
        

