    # RELENTLESS SEARCH LOGIC - NEVER RETURN NONE, NEVER CREATE FAKE DATA
    # -------------------------------------------------------------------------
    async def ensure_position_present(self, account_key: str, symbol: str, position_side: str, position_key: Optional[str] = None) -> Optional[Position]:
        try:
            if not position_key:
                position_key = construct_position_key(account_key, symbol, position_side)

            # 1. Check Memory (Fastest)
            position = self.positions_by_account.get(account_key, {}).get(position_key)
            if position:
                return position
            
            # 2. Check Global Memory (In case it drifted)
            existing_global = self.positions.get(position_key)
            if existing_global:
                self.positions_by_account.setdefault(account_key, {})[position_key] = existing_global
                return existing_global
            
            self.logger.warning(f"🔍 [RELENTLESS_SEARCH] {position_key} missing from memory. Starting deep disk scan...")

            # 3. RELENTLESS DISK SEARCH
            # Scan ALL files, ignoring naming conventions, looking for the data payload
            found_position = await self._relentless_disk_search(account_key, symbol, position_side)
            
            if found_position:
                # We found the REAL data.
                age = (datetime.now(timezone.utc) - found_position.last_updated).total_seconds() if found_position.last_updated else 999
                self.logger.info(f"✅ [RELENTLESS_SEARCH] FOUND {position_key} in deep storage! (Last Updated: {age:.0f}s ago). Restoring.")
                
                # Add to memory maps
                self.positions_by_account.setdefault(account_key, {})[position_key] = found_position
                self.positions[position_key] = found_position
                
                # Force a broadcast so other components (Redis/Quick) get it immediately
                if hasattr(self, '_broadcast_positions_to_redis'):
                    asyncio.create_task(self._broadcast_positions_to_redis(account_key, {position_key: found_position.to_dict()}))
                
                return found_position

            # 4. CRITICAL FAILURE LOGGING
            # If we reach here, the data is physically gone from the disk. 
            # We DO NOT create fake data. We yell.
            self.logger.critical(f"❌❌ [RELENTLESS_SEARCH] FAILED for {position_key}. Scanned ALL files in {account_key}/ and backups/. Data not found.")
            
            # If we return None here, the calling code MUST handle it (by skipping), 
            # but we have guaranteed we tried everything to find the history.
            return None

        except Exception as e:
            self.logger.error(f"[ensure_position_present] Crash searching for {position_key}: {e}", exc_info=True)
            return None

    async def _relentless_disk_search(self, account_key: str, target_symbol: str, target_side: str) -> Optional[Position]:
        import glob
        
        target_symbol = target_symbol.strip().upper()
        target_side = target_side.strip().upper()
        
        best_candidate: Optional[Position] = None
        best_ts = 0.0

        # 1. Define Search Paths
        base_dir = self.base_path / account_key
        backup_dir = base_dir / "backups"
        
        # We look at EVERYTHING. Main files, updates, changes, and all backups.
        files_to_scan = []
        
        # Priority 1: Active Files (Likely location)
        files_to_scan.extend(base_dir.glob("*.json"))
        
        # Priority 2: Backups (History)
        if backup_dir.exists():
            # Sort backups by modified time, newest first
            all_backups = sorted(backup_dir.glob("*.json"), key=lambda x: x.stat().st_mtime, reverse=True)
            # Scan top 50 backups (optimization: unlikely to be older)
            files_to_scan.extend(all_backups[:50])

        for file_path in files_to_scan:
            try:
                # Fast Check: Skip if file is empty
                if file_path.stat().st_size < 10: continue

                # Load content
                async with LimitedAioOpen(str(file_path), "rb") as f:
                    content = await f.read()
                    data = safe_json_loads(content)

                if not isinstance(data, dict): continue

                # Search Dictionary Values
                # We don't care about the Key. We care about the Data.
                for key, payload in data.items():
                    if not isinstance(payload, dict): continue
                    
                    # Check Symbol Match
                    s = payload.get("symbol")
                    if not s or str(s).strip().upper() != target_symbol: continue
                    
                    # Check Side Match
                    # Handle "LONG"/"SHORT" and "BOTH" if applicable
                    ps = payload.get("positionSide") or payload.get("position_side")
                    if not ps or str(ps).strip().upper() != target_side: continue

                    # FOUND A MATCH. Is it the best one?
                    try:
                        candidate = Position.from_dict(payload)
                        
                        # Timestamp logic
                        ts_val = candidate.last_updated
                        ts_epoch = 0.0
                        if ts_val:
                            if isinstance(ts_val, datetime): ts_epoch = ts_val.timestamp()
                            elif isinstance(ts_val, (int, float)): ts_epoch = float(ts_val)
                        
                        # Determine quality: Non-zero positions prefered over zero
                        # If we have a non-zero position, it wins unless we find a NEWER non-zero
                        current_is_nonzero = abs(candidate.positionAmt) > 0
                        best_is_nonzero = best_candidate and abs(best_candidate.positionAmt) > 0

                        if current_is_nonzero and not best_is_nonzero:
                            best_candidate = candidate
                            best_ts = ts_epoch
                        elif current_is_nonzero and best_is_nonzero:
                            if ts_epoch > best_ts:
                                best_candidate = candidate
                                best_ts = ts_epoch
                        elif not current_is_nonzero and not best_is_nonzero:
                            if ts_epoch > best_ts:
                                best_candidate = candidate
                                best_ts = ts_epoch
                                
                    except Exception:
                        continue

            except Exception:
                # Ignore individual file read errors
                continue

        return best_candidate

    async def _write_positions_payload_to_files(self, account_key: str, payload: Dict[str, Any]) -> None:
        # CRITICAL: DISABLED - This method writes from Redis/file payload (stale data)
        # Only atomic_save_positions (from ez_positions.py) should write position files - it reads from memory (fresh data)
        logger.debug(f"[_write_positions_payload_to_files][{account_key}] ⚠️ DISABLED - only atomic_save_positions should write position files")
        return
        # OLD CODE BELOW - DISABLED
        expected_count = self._get_expected_symbol_count()
        if not isinstance(payload, dict) or len(payload) == 0 or len(payload) < expected_count * 2:
            return
        per_side: Dict[str, Dict[str, Any]] = {'LONG': {}, 'SHORT': {}}
        for position_key, entry in payload.items():
            if not isinstance(position_key, str) or not isinstance(entry, dict):
                continue
            if position_key.upper() in ('POSITIONS', 'META', 'TIMESTAMP', 'TIME', 'DATA', 'INFO', 'ACCOUNT_KEY', 'SIDE'):
                continue
            side = (entry.get('positionSide') or entry.get('position_side') or '').upper()
            if side not in ('LONG', 'SHORT'):
                continue
            per_side[side][position_key] = entry
        for side, content in per_side.items():
            if len(content) == 0 or len(content) < expected_count:
                continue
            file_path = self.get_position_file(account_key, side)
            file_path.parent.mkdir(parents=True, exist_ok=True)
            await self._atomic_write(file_path, content)

    async def try_add_order_redis(self, lock_key: str, expiry_seconds: int = 45) -> bool:
        if not hasattr(self, "_local_locks"):
            self._local_locks: Dict[str, Dict[str, float]] = {}
            self._local_locks_cleanup_task: Optional[asyncio.Task] = None
        normalized = lock_key if lock_key.startswith("execute_now:") else f"execute_now:{lock_key}"
        client = await self._ensure_redis_client()
        if client:
            try:
                result = await client.set(normalized, "1", ex=expiry_seconds, nx=True)
                if result:
                    return True
            except Exception as exc:
                logger.debug(f"[locks] Redis setnx failed for {normalized}: {exc}")
        return await self._try_local_lock(normalized, expiry_seconds)

    async def _try_local_lock(self, normalized_key: str, expiry_seconds: int) -> bool:
        now = time.time()
        expired = [key for key, meta in self._local_locks.items() if meta["expires"] <= now]
        for key in expired:
            self._local_locks.pop(key, None)
        if normalized_key in self._local_locks and self._local_locks[normalized_key]["expires"] > now:
            return False
        self._local_locks[normalized_key] = {"expires": now + expiry_seconds}
        if not self._local_locks_cleanup_task or self._local_locks_cleanup_task.done():
            self._local_locks_cleanup_task = asyncio.create_task(self._cleanup_local_locks())
        return True

    async def _cleanup_local_locks(self) -> None:
        try:
            while self._local_locks:
                await asyncio.sleep(5.0)
                now = time.time()
                expired = [key for key, meta in self._local_locks.items() if meta["expires"] <= now]
                for key in expired:
                    self._local_locks.pop(key, None)
        except asyncio.CancelledError:
            pass
    
    async def clear_active_lock(self, position_key: str) -> None:
        keys = [position_key]
        if position_key and not position_key.startswith("execute_now:"):
            keys.extend([f"execute_now:{position_key}", f"execute_now:{position_key}:BUY", f"execute_now:{position_key}:SELL"])
        try:
            redis_manager = getattr(self, "redis_manager", None)
            if redis_manager and hasattr(redis_manager, "delete"):
                for key in keys:
                    try:
                        await redis_manager.delete(key)
                    except Exception as exc:
                        logger.debug(f"[locks] redis_manager delete failed for {key}: {exc}")
            client = await self._ensure_redis_client()
            if client:
                for key in keys:
                    try:
                        await client.delete(key)
                    except Exception as exc:
                        logger.debug(f"[locks] redis delete failed for {key}: {exc}")
            if hasattr(self, "_local_locks"):
                for key in keys:
                    self._local_locks.pop(key, None)
        except Exception as exc:
            logger.debug(f"[locks] clear_active_lock error for {position_key}: {exc}")
    
    async def is_order_locked(self, position_key: str) -> bool:
        keys = [position_key]
        if position_key and not position_key.startswith("execute_now:"):
            keys.extend([f"execute_now:{position_key}", f"execute_now:{position_key}:BUY", f"execute_now:{position_key}:SELL"])
        normalized_keys = [k if k.startswith("execute_now:") else f"execute_now:{k}" for k in keys]
        all_keys = list(set(keys + normalized_keys))
        try:
            redis_manager = getattr(self, "redis_manager", None)
            if redis_manager and hasattr(redis_manager, "get"):
                for key in all_keys:
                    try:
                        value = await redis_manager.get(key)
                        if value is not None:
                            return True
                    except Exception as exc:
                        logger.debug(f"[locks] redis_manager get failed for {key}: {exc}")
                        continue
            client = await self._ensure_redis_client()
            if client:
                for key in all_keys:
                    try:
                        value = await client.get(key)
                        if value is not None:
                            return True
                    except Exception as exc:
                        logger.debug(f"[locks] redis get failed for {key}: {exc}")
                        continue
            if hasattr(self, "_local_locks"):
                now = time.time()
                for key in all_keys:
                    meta = self._local_locks.get(key)
                    if meta and meta.get("expires", 0.0) > now:
                        return True
            return False
        except Exception as exc:
            logger.debug(f"[locks] is_order_locked error for {position_key}: {exc}")
            return False


