    async def start_account_monitors(self) -> None:
        """Start fetching positions every 30 seconds, WebSocket listeners, and periodic saves"""
        try:
            if not self._should_enable_account_monitors():
                logger.warning("[sta rt_account_monitors] Account monitors disabled (no accounts)")
                return
            # Check watchdog flag - if external fetcher failed, enable internal fetcher
            internal_fetcher_flag = self.base_path / ".internal_fetcher_enabled"
            if internal_fetcher_flag.exists():
                logger.critical(f"[st art_account_monitors] 🚨 Watchdog signaled external fetcher failed - ENABLING INTERNAL FETCHER")
                self._enable_auto_fetch = True
            disabled_flag = self.base_path / ".internal_fetcher_disabled"
            if disabled_flag.exists():
                logger.debug(f"[start_ account_monitors] Watchdog signaled external fetcher working - disabling internal fetcher")
                self._enable_auto_fetch = False
            logger.debug(f"[start_acco unt_monitors] Starting monitors for {len(self.accounts)} accounts: {list(self.accounts.keys())} (REST fetch: 30s, WebSocket: real-time, auto_fetch={self._enable_auto_fetch})")
            self._account_monitor_stop = False
            if not hasattr(self, '_periodic_full_save_task') or self._periodic_full_save_task is None or self._periodic_full_save_task.done():
                self._periodic_full_save_task = asyncio.create_task(self._periodic_full_save_loop())
                logger.debug("[start_acc ount_monitors] Started periodic full save loop")
            if not hasattr(self, '_periodic_update_zero_positions_task') or self._periodic_update_zero_positions_task is None or self._periodic_update_zero_positions_task.done():
                self._periodic_update_zero_positions_task = asyncio.create_task(self._periodic_update_zero_positions())
                logger.debug("[start_account_mo nitors] Started periodic update zero positions task (every hour)")
            for account_key, account in self.accounts.items():
                # CRITICAL: Only start REST polling if auto-fetch is enabled (ez_positions.py handles fetching when disabled)
                if getattr(self, '_enable_auto_fetch', True):
                    if account_key not in self._rest_poll_tasks or self._rest_poll_tasks[account_key].done():
                        async def _poll_loop_wrapper(ak):
                            try:
                                if config.VERBOSE_FETCH_LOGGING: logger.info(f"[start_ account_monitors][{ak}] 🚨 CALLING _rest_poll_loop NOW")
                                await self._rest_poll_loop(ak)
                                if config.VERBOSE_FETCH_LOGGING: logger.info(f"[start_ account_monitors][{ak}] _rest_poll_loop COMPLETED")
                            except Exception as poll_err:
                                logger.error(f"[start _account_monitors][{ak}] CRITICAL: _rest_poll_loop FAILED: {poll_err}", exc_info=True)
                        self._rest_poll_tasks[account_key] = asyncio.create_task(_poll_loop_wrapper(account_key))
                    else:
                        task_status = "running" if not self._rest_poll_tasks[account_key].done() else "done"
                        logger.warning(f"[start_acc ount_monitors][{account_key}] ⚠️ REST polling loop task already exists (status: {task_status}) - recreating if done")
                        if self._rest_poll_tasks[account_key].done():
                            try:
                                result = self._rest_poll_tasks[account_key].result()
                                logger.warning(f"[star t_account_monitors][{account_key}] Previous task completed with result: {result}")
                            except Exception as e:
                                logger.error(f"[start_a ccount_monitors][{account_key}] Previous task failed: {e}")
                            self._rest_poll_tasks[account_key] = asyncio.create_task(self._rest_poll_loop(account_key))
                            logger.debug(f"[start_accou nt_monitors][{account_key}] REST polling loop task recreated (30s interval)")

                # # CRITICAL: Only start WebSocket if auto-fetch is enabled (ez_positions.py starts its own WebSocket after positions are loaded)
                # if getattr(self, '_enable_auto_fetch', True):
                if account_key not in self.websocket_managers:
                    api_key = getattr(account, 'api_key', None) or getattr(account, 'api_key_plain', None)
                    api_secret = getattr(account, 'api_secret', None) or getattr(account, 'api_secret_plain', None)
                    if not api_key or not api_secret:
                        logger.warning(f"[start_accou nt_monitors][{account_key}] ⚠️ Missing API credentials; skipping WebSocket manager initialization")
                    else:
                        manager = WebSocketManager(account_keys=[account_key], api_key=api_key, api_secret=api_secret, config=self.config, symbols=None, service=self)
                        self.websocket_managers[account_key] = manager
                        if not self.primary_ws_manager:
                            self.primary_ws_manager = manager
                        async def _ws_start_wrapper(ak, mgr):
                            try:
                                logger.info(f"[start_ account_monitors][{ak}] 🚨 Starting WebSocket manager for real-time updates")
                                await mgr.start(ak)
                                logger.info(f"[start_ account_monitors][{ak}] WebSocket manager started and listening")
                            except Exception as ws_err:
                                logger.error(f"[start _account_monitors][{ak}] CRITICAL: WebSocket manager start FAILED: {ws_err}", exc_info=True)
                        asyncio.create_task(_ws_start_wrapper(account_key, manager))
                        #asyncio.create_task(manager.ensure_mark_price_tasks())
                        logger.info(f"[start_accou nt_monitors][{account_key}] WebSocket manager task created for real-time position updates")


        except Exception as e:
            logger.error(f"[start_ac count_monitors] CRITICAL: Failed to start account monitors: {e}", exc_info=True)

    async def stop_account_monitors(self) -> None:
        self._account_monitor_stop = True
        for task in list(self._rest_poll_tasks.values()):
            if task and not task.done():
                task.cancel()
        for task in list(self._rest_poll_tasks.values()):
            if task:
                try:
                    await task
                except asyncio.CancelledError:
                    pass
                except Exception as exc:
                    logger.debug(f"[positions_service] monitor task exit error: {exc}")
        self._rest_poll_tasks.clear()
        for manager in list(self.websocket_managers.values()):
            try:
                await manager.stop()
            except Exception as exc:
                logger.debug(f"[{','.join(manager.account_keys)}] websocket manager stop error: {exc}")
        self.websocket_managers.clear()
        self.primary_ws_manager = None
        for session in list(self._account_sessions.values()):
            try:
                if session and not session.closed:
                    await session.close()
            except Exception:
                pass
        self._account_sessions.clear()
        self._account_listen_keys.clear()


    async def _broadcast_positions_to_redis(self, account_key: str, positions_dict: Dict[str, Any], allow_incomplete: bool = True) -> None:
        if config.VERBOSE_FETCH_LOGGING: logger.debug(f"[REDIS_BROADCAST_ENTER][{account_key}] 🚨 ENTERED _broadcast_positions_to_redis")
        try:
            redis_manager = self.indicator_bridge.redis_manager if self.indicator_bridge and self.indicator_bridge.redis_manager else None
            if not redis_manager:
                try: 
                    redis_manager = await get_simple_redis_manager()
                except Exception as redis_err:
                    logger.error(f"[REDIS_BROADCAST][{account_key}] Failed to get Redis manager: {redis_err}", exc_info=True)
                    return
            if not redis_manager:
                logger.error(f"[REDIS_BROADCAST][{account_key}] Redis manager is None - cannot broadcast")
                return
            redis_key = f"positions:{account_key}"
            # CRITICAL: Use positions_dict parameter (already filtered by side) instead of rebuilding from ALL positions
            # This ensures we count only the positions for THIS side, not all positions
            combined_data = positions_dict.copy() if positions_dict else {}
            # Also get ALL positions for Redis key (both sides) - but use positions_dict for broadcast
            account_positions = self.positions_by_account.get(account_key, {})
            all_positions_data = {}
            now = datetime.now(timezone.utc)
            for pos_key, pos_obj in account_positions.items():
                if pos_obj and hasattr(pos_obj, "to_dict"):
                    if not hasattr(pos_obj, "last_updated") or not pos_obj.last_updated:
                        pos_obj.last_updated = now
                    elif (now - pos_obj.last_updated).total_seconds() > 3600:
                        pos_obj.last_updated = now
                    all_positions_data[pos_key] = pos_obj.to_dict()
            logger.debug(f"[REDIS_BROADCAST][{account_key}] Combined {len(combined_data)} positions {len(all_positions_data)} total positions")
            expected_symbol_count = self._get_expected_symbol_count()  # Expected per side (len(symbols.json))
            expected_count = expected_symbol_count  # Single side = len(symbols.json)
            actual_position_count = len(combined_data) 
            # if actual_position_count < expected_count:
            #     logger.critical(f"[REDIS_BROADCAST_COUNT][{account_key}] 🚨 CRITICAL: {account_key} has {actual_position_count} positions but expected {expected_count} from symbols.json - POSITIONS MISSING!")
            # elif actual_position_count > expected_count:
            #     logger.warning(f"[REDIS_BROADCAST_COUNT][{account_key}] ⚠️ {account_key} has {actual_position_count} positions but expected {expected_count} from symbols.json - extra positions detected")
            meta = {
                "positions_last_sync": self._iso(self.positions_last_sync) if isinstance(self.positions_last_sync, datetime) else datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%S.%fZ'),
                "timestamp": datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%S.%fZ'),
                "expected_count": expected_count,
                "actual_count": actual_position_count }
            payload_bytes = json_dumps({"positions": all_positions_data, "meta": meta})
            await redis_manager.set(redis_key, payload_bytes, ex=300)
            delta_bytes = json_dumps({"account_key": account_key, "side": "all", "positions": combined_data, "meta": meta, "type": "full"})
            channel = REDIS_CHANNELS.get("position_updates", "position_updates")
            await redis_manager.publish(channel, delta_bytes)
        except Exception as e:
            logger.error(f"[REDIS_BROADCAST_EXCEPTION][{account_key}] Redis broadcast failed: {e}", exc_info=True)     
            channel = REDIS_CHANNELS.get("position_updates", "position_updates")
            await redis_manager.publish(channel, json.dumps({"account_key": account_key, "side": "all", "positions": combined_data, "meta": meta, "type": "full"}))
            logger.debug(f"[REDIS_BROADCAST][{account_key}] Published to Redis channel")
        except Exception as e:
            logger.error(f"[REDIS_BROADCAST_EXCEPTION][{account_key}] Redis broadcast failed: {e}", exc_info=True)

    async def _broadcast_position_updates_to_redis(self, account_key: str, updated_position_keys: Set[str]) -> None:
        try:
            if not updated_position_keys:
                return
                
            redis_manager = self.indicator_bridge.redis_manager if self.indicator_bridge and self.indicator_bridge.redis_manager else None
            if not redis_manager:
                try:
                    redis_manager = await get_simple_redis_manager()
                except Exception as redis_err:
                    logger.error(f"[REDIS_UPDATES][{account_key}] Failed to get Redis manager: {redis_err}")
                    return
            if not redis_manager:
                return

            account_positions = self.positions_by_account.get(account_key, {})
            updates_dict: Dict[str, Any] = {}
            
            for pos_key in updated_position_keys:
                pos_obj = account_positions.get(pos_key)
                if pos_obj and hasattr(pos_obj, "to_dict"):
                    updates_dict[pos_key] = pos_obj.to_dict()
            
            if not updates_dict:
                return

            # Helper for safe JSON serialization (Fixes "set is not JSON serializable")
            def json_safe(obj):
                if isinstance(obj, set):
                    return list(obj)
                if isinstance(obj, datetime):
                    return obj.strftime('%Y-%m-%dT%H:%M:%S.%fZ')
                return str(obj)

            # 1. Update Full State Key
            combined_data = {}
            now = datetime.now(timezone.utc)
            for pos_key, pos_obj in account_positions.items():
                if pos_obj and hasattr(pos_obj, "to_dict"):
                    if not hasattr(pos_obj, "last_updated") or not pos_obj.last_updated:
                        pos_obj.last_updated = now
                    combined_data[pos_key] = pos_obj.to_dict()
            
            redis_key = f"positions:{account_key}"
            expected_symbol_count = self._get_expected_symbol_count()
            actual_position_count = len(combined_data)
            
            meta = {
                "positions_last_sync": self._iso(self.positions_last_sync) if isinstance(self.positions_last_sync, datetime) else datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%S.%fZ'),
                "timestamp": datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%S.%fZ'),
                "expected_count": expected_symbol_count,
                "actual_count": actual_position_count,
            }
            
            payload = {"positions": combined_data, "meta": meta}
            
            # USE json_safe HERE
            await redis_manager.set(redis_key, json.dumps(payload, default=json_safe), ex=300)
            
            # 2. Publish Delta Update
            meta_delta = {"timestamp": datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%S.%fZ'), "type": "delta"}
            channel = REDIS_CHANNELS.get("position_updates_delta", "position_updates_delta")
            
            # USE json_safe HERE
            await redis_manager.publish(channel, json.dumps({
                "account_key": account_key, 
                "positions": updates_dict, 
                "meta": meta_delta, 
                "type": "delta"
            }, default=json_safe))
            
            if config.VERBOSE_FETCH_LOGGING:
                logger.debug(f"[REDIS_UPDATES][{account_key}] Published delta update for {len(updates_dict)} positions")
                
        except Exception as e:
            logger.error(f"[REDIS_UPDATES_EXCEPTION][{account_key}] Redis broadcast failed: {e}", exc_info=True)

    async def _periodic_update_zero_positions(self) -> None:
        await asyncio.sleep(10) 
        while not self._account_monitor_stop:
            try:
                if getattr(self.config, 'VERBOSE_FETCH_LOGGING', False):
                    logger.info("[_periodic_update_zero_positions] 🔄 Starting 1-minute evaluation of zero positions...")
                
                updated_count = 0
                
                # Iterate through all accounts
                for account_key in list(self.accounts.keys()):
                    account_positions = self.positions_by_account.get(account_key, {})
                    
                    # Iterate through all positions in the account
                    for position_key, position in list(account_positions.items()):
                        if not position:
                            continue
                            
                        # Check if position amount is effectively zero
                        positionAmt = abs(float(getattr(position, 'positionAmt', 0) or 0))
                        
                        # We only want to evaluate zero/unchanged positions here
                        if positionAmt == 0.0:
                            try:
                                symbol = position.symbol
                                
                                # 1. Get the current price (Mark Price)
                                current_price = float(getattr(position, 'mark_price', 0) or 0.0)
                                
                                # Fallback if price is missing in position object
                                if current_price <= 0:
                                    try:
                                        from utils import quick_price, orjson_default
                                        current_price = await quick_price(symbol) or 0.0
                                    except Exception:
                                        pass
                                        
                                # 2. Call handle_unchanged_position if we have a price
                                if current_price > 0:
                                    # This updates last_updated, mark_price_last_updated, and recalculates gain/pnl
                                    await self.handle_unchanged_position(
                                        position, 
                                        position_key, 
                                        0.0, # amt_abs is 0x
                                        current_price
                                    )
                                    updated_count += 1
                                    
                            except Exception as e:
                                logger.error(f"[_periodic_update_zero_positions] Error evaluating {position_key}: {e}", exc_info=True)
                
                if updated_count > 0 and getattr(self.config, 'VERBOSE_FETCH_LOGGING', False):
                    logger.info(f"[_periodic_update_zero_positions] Evaluated and updated timestamps for {updated_count} zero positions")
                    
            except Exception as e:
                logger.error(f"[_periodic_update_zero_positions] Error in periodic task: {e}", exc_info=True)
            
            # Wait 1 minute before the next evaluation cycle
            await asyncio.sleep(300)      

