    async def _periodic_full_save_loop(self) -> None:
        await asyncio.sleep(1.0)
        while not self._account_monitor_stop:
            try:
                now = time.time()
                if now - self._last_full_save_time >= self._full_save_interval:
                    logger.debug(f"[_periodic_full_save_loop] Running periodic full save (every {self._full_save_interval}s)")
                    # CRITICAL: DISABLED - ez_positions_service.py should NOT save - only realtime scripts should write
                    # try:
                    #     from ez_positions import atomic_save_positions
                    #     save_tasks = []
                    #     for account_key in self.accounts.keys():
                    #         save_tasks.append(atomic_save_positions(self, account_key))
                    #     if save_tasks:
                    #         await asyncio.gather(*save_tasks, return_exceptions=True)
                    #     logger.debug(f"[_periodic_full_save_loop] Periodic full save completed for all accounts")
                    # except ImportError:
                    #     logger.warning(f"[_periodic_full_save_loop] ⚠️ Cannot import atomic_save_positions - skipping save")
                    # except Exception as save_err:
                    #     logger.error(f"[_periodic_full_save_loop] Save failed: {save_err}", exc_info=True)
                    logger.debug(f"[_periodic_full_save_loop] ⏸️ SAVE DISABLED - only realtime scripts should write")
                    self._last_full_save_time = now
                await asyncio.sleep(self._full_save_interval)
            except asyncio.CancelledError:
                break
            except Exception as e:
                logger.error(f"[_periodic_full_save_loop] Error: {e}", exc_info=True)
                await asyncio.sleep(self._full_save_interval)

