    async def save_graceful_exit_list(self) -> None:
        """Persist the graceful exit list to disk."""
        try:
            path = self.base_path / "graceful_exits.json"
            data = list(self.positions_to_gracefully_exit)
            async with aiofiles.open(str(path), "w") as f:
                await f.write(json.dumps(data))
        except Exception as e:
            self.logger.error(f"[save_graceful_exit_list] Failed: {e}")

    async def add_symbol_to_fin_list(self, symbol: str) -> bool:
        rel_path = getattr(self.config, 'SYMBOLS_FIN', None)
        path_obj = Path(rel_path)
        if not path_obj.is_absolute():
            path_obj = self.base_path / rel_path
        current_symbols = set()
        if await aio_os.path.exists(str(path_obj)):
            try:
                async with aiofiles.open(str(path_obj), "rb") as f:
                    content = await f.read()
                    if content:
                        data = json.loads(content)
                        if isinstance(data, list):
                            current_symbols = set(data)
                        elif isinstance(data, dict):
                            current_symbols = set(data.get("symbols", []))
            except Exception as e:
                self.logger.error(f"[fin] Error reading existing file: {e}")
        if symbol in current_symbols:
            return True
        current_symbols.add(symbol)
        sorted_list = sorted(list(current_symbols))
        try:
            async with aiofiles.open(str(path_obj), "w") as f:
                await f.write(json.dumps(sorted_list, indent=2))
            self.logger.info(f"[fin] Added {symbol} to symbols_fin.json (Total: {len(sorted_list)})")
        except Exception as e:
            self.logger.error(f"[fin] Failed to write file: {e}")

    async def _universe_maintenance_loop(self) -> None:
        self.logger.info("[UNIVERSE_MAINTENANCE] 🚀 Loop started - Running initial cleanup...")
        try:
            await asyncio.wait_for(self.cleanup_positions(force=False), timeout=40.0)
        except asyncio.TimeoutError:
            self.logger.error("[UNIVERSE_MAINTENANCE] ⏳ Initial cleanup TIMED OUT")
        except Exception as e:
            self.logger.error(f"[UNIVERSE_MAINTENANCE] Initial cleanup failed: {e}", exc_info=True)
        while not self._housekeeping_stop:
            await asyncio.sleep(180.0)
            try:
                await asyncio.wait_for(self.cleanup_positions(force=True), timeout=40.0)
            except asyncio.TimeoutError:
                self.logger.warning("[UNIVERSE_MAINTENANCE] ⏳ Cleanup timed out (skipping)")
            except Exception as e:
                self.logger.error(f"[UNIVERSE_MAINTENANCE] Error: {e}", exc_info=True)

    async def cleanup_positions(self, force: bool = False):
        persistence_file = self.base_path / "universe_persistence.json"
        tradeable_file = self.base_path / "tradeable_keys.json"
        symbols_json_file = self.base_path / "symbols.json"
        symbols_active_file = self.base_path / "symbols_active.json"
        
        if not force and tradeable_file.exists():
            try:
                if (time.time() - tradeable_file.stat().st_mtime) < 300: return
            except Exception: pass

        async def _resilient_load(path: Path):
            if not path.exists(): return None
            try:
                async with aiofiles.open(str(path), 'rb') as f:
                    content = await f.read()
                    if not content: return None
                    try: return json.loads(content)
                    except json.JSONDecodeError:
                        # Attempt Basic Repair for concatenated JSON error
                        try:
                            s = content.decode('utf-8').strip()
                            if s.endswith(']'):
                                # Find last valid bracket
                                last_idx = s.rfind(']')
                                if last_idx != -1: return json.loads(s[:last_idx + 1])
                        except Exception: pass
                        return None
            except Exception:  return None

        async def load_set(attr):
            try:
                rel = getattr(self.config, attr, None)
                if not rel: return set()
                path = Path(rel)
                if not path.is_absolute(): path = self.base_path / rel
                data = await _resilient_load(path)
                if not data: return set()

                if isinstance(data, dict): data = data.get('symbols', []) or data.get('pairs', [])
                if isinstance(data, list):
                    return set(str(s).strip().upper() for s in data if isinstance(s, (str, int)))
            except Exception:  return set()
            return set()

        async def load_leaderboard(attr):
            try:
                rel = getattr(self.config, attr, None)
                if not rel: return set()
                path = Path(rel)
                if not path.is_absolute(): path = self.base_path / rel
                data = await _resilient_load(path)
                if not data: return set()

                symbols = set()
                if isinstance(data, list):
                    for item in data:
                        if isinstance(item, dict):
                            s = item.get('symbol')
                            if s: symbols.add(str(s).strip().upper())
                        elif isinstance(item, str):
                            symbols.add(item.strip().upper())
                return symbols
            except Exception: return set()
            return set()

        # --- 2. LOAD DATA ---
        try:
            # Load Account Lists
            results = await asyncio.gather(
                load_set('SYMBOLS_ANG_LONG'), load_set('SYMBOLS_ANG_SHORT'),
                load_set('SYMBOLS_INF_LONG'), load_set('SYMBOLS_INF_SHORT'),
                load_set('SYMBOLS_FLZ'), load_set('SYMBOLS_MEN'), load_set('SYMBOLS_FIN'),
                return_exceptions=True
            )
            ang_l, ang_s, inf_l, inf_s, flz_s, men_s, fin_s = [r if isinstance(r, set) else set() for r in results]
            
            # Load Leaderboards
            lb_results = await asyncio.gather(
                load_leaderboard('WINNERS_20_FILE'), load_leaderboard('LOSERS_20_FILE'),
                load_leaderboard('WINNERS_15M_FILE'), load_leaderboard('LOSERS_15M_FILE'),
                return_exceptions=True
            )
            w20, l20, w15, l15 = [r if isinstance(r, set) else set() for r in lb_results]

            # Load Master Whitelist (symbols.json) - Crucial for cleanup
            master_whitelist = set()
            raw_whitelist = await _resilient_load(symbols_json_file)
            if raw_whitelist:
                if isinstance(raw_whitelist, list): master_whitelist = set(raw_whitelist)
                elif isinstance(raw_whitelist, dict): master_whitelist = set(raw_whitelist.get('symbols', []))

        except Exception as e:
            self.logger.error(f"[cleanup] Failed to load data files: {e}")
            return

        winners_union = w20 | w15
        losers_union = l20 | l15
        
        # Load Existing Persistence
        persistence = await _resilient_load(persistence_file) or {}

        # --- 3. CONFIGURATION & TIME ---
        all_accounts = getattr(self.config, 'ACCOUNT_KEYS', ['ang', 'inf', 'men', 'flz', 'fin'])
        standard_persist_minutes = float(getattr(self.config, 'PERSIST', 1800)) 
        short_term_persist_minutes = 90.0
        pure_short_term_symbols = (w15 | l15) - (w20 | l20 | ang_l | ang_s | inf_l | inf_s | flz_s | men_s | fin_s)

        now_ts = time.time()
        now_dt = datetime.now(timezone.utc)
        is_nuke_window = (now_dt.hour == 5 and now_dt.minute < 15) # 5:00 AM - 5:15 AM UTC

        new_persistence = {}
        final_tradeable_set = set()

        symbols_active_set = set()
        for account_key in all_accounts:
            strict_set = set()

            if account_key == 'flz':
                for s in flz_s:
                    is_w = s in w20; is_l = s in l20
                    if is_w:
                        strict_set.add(f"{account_key}:{s}_LONG")
                        symbols_active_set.add(s)
                    elif is_l:
                        strict_set.add(f"{account_key}:{s}_SHORT")
                        symbols_active_set.add(s)
                    else:
                        strict_set.add(f"{account_key}:{s}_LONG")
                        strict_set.add(f"{account_key}:{s}_SHORT")
                        symbols_active_set.add(s)

            elif account_key == 'men':
                for s in men_s:
                    if s in winners_union: strict_set.add(f"{account_key}:{s}_LONG")
                    if s in losers_union: strict_set.add(f"{account_key}:{s}_SHORT")
                    symbols_active_set.add(s)
            elif account_key == 'fin':
                for s in men_s:
                    if s in winners_union: strict_set.add(f"{account_key}:{s}_LONG")
                    if s in losers_union: strict_set.add(f"{account_key}:{s}_SHORT")
                    symbols_active_set.add(s)
            # elif account_key == 'fin':
            #     for s in fin_s:
            #         if s in winners_union: strict_set.add(f"{account_key}:{s}_LONG")
            #         if s in losers_union: strict_set.add(f"{account_key}:{s}_SHORT")
            #         symbols_active_set.add(s)

            elif account_key == 'ang':
                for s in ang_l:
                    strict_set.add(f"{account_key}:{s}_LONG")
                    symbols_active_set.add(s)
                for s in ang_s:
                    strict_set.add(f"{account_key}:{s}_SHORT")
                    symbols_active_set.add(s)

            elif account_key == 'inf':
                for s in inf_l:
                    if s in w15: strict_set.add(f"{account_key}:{s}_LONG")
                    symbols_active_set.add(s)
                for s in inf_s:
                    if s in l15: strict_set.add(f"{account_key}:{s}_SHORT")
                    symbols_active_set.add(s)
            for k in strict_set:
                new_persistence[k] = now_ts
            for k, ts in persistence.items():
                if not k.startswith(account_key): continue
                if k in new_persistence: continue
                try:
                    sym = k.split(':')[1].replace('_LONG', '').replace('_SHORT', '')
                    if master_whitelist and sym not in master_whitelist: continue
                    is_short_term = sym in pure_short_term_symbols
                    limit_minutes = short_term_persist_minutes if is_short_term else standard_persist_minutes
                    if (now_ts - ts) < (limit_minutes * 60):
                        new_persistence[k] = ts
                        # Also keep symbol active if persisting
                        symbols_active_set.add(sym)
                except Exception:  pass

            allowed_set = set(k for k in new_persistence if k.startswith(account_key))

            # --- HEDGE & ACTIVE POSITIONS ---
            protected_hedges = set()
            try:
                tracker_path = self.base_path / account_key / "tracker.json"
                data = await _resilient_load(tracker_path)
                if data:
                    hedges = data.get('hedges', {})
                    if isinstance(hedges, dict): protected_hedges.update(hedges.keys())
                    active_h = data.get('active_hedges', [])
                    if isinstance(active_h, list):
                        for h in active_h:
                            if isinstance(h, dict): protected_hedges.add(h.get('position_key'))
            except Exception:  pass

            positions = self.positions_by_account.get(account_key, {})
            zombie_hedges = set()

            for hedge_key in list(protected_hedges):
                pos = positions.get(hedge_key)
                if pos and abs(float(getattr(pos, 'positionAmt', 0.0))) > 0.0001:
                    allowed_set.add(hedge_key)
                    # Add hedge symbol to active set
                    try:
                        s = hedge_key.split(':')[1].replace('_LONG', '').replace('_SHORT', '')
                        symbols_active_set.add(s)
                    except Exception:  pass
                else:
                    zombie_hedges.add(hedge_key)

            for k, v in positions.items():
                if not k.startswith(account_key): continue
                amt = abs(float(getattr(v, 'positionAmt', 0.0)))
                
                if amt > 0:
                    is_valid = k in allowed_set
                    is_hedge = k in protected_hedges
                    if account_key == 'fin' and is_valid and s not in fin_s:
                        await self.add_symbol_to_fin_list(s)
                    if is_valid or is_hedge:
                        allowed_set.add(k)
                        s = k.split(':')[1].replace('_LONG', '').replace('_SHORT', '')
                        symbols_active_set.add(s)

                    else:
                        # ROGUE POSITION (Not in universe, not a hedge, but open)
                        # Check if we should NUKE it
                        age_minutes = 0
                        if getattr(v, 'opened_at', None): 
                            age_minutes = (now_dt - v.opened_at).total_seconds() / 60
                        
                        should_nuke = is_nuke_window or (age_minutes > (standard_persist_minutes * 1.5))
                        
                        if should_nuke:
                            self.logger.warning(f"☢️ [CLEANUP] Nuking rogue {k} (Age: {int(age_minutes)}m)")
                            if self.trade_manager:
                                asyncio.create_task(self.trade_manager.execute_now(
                                    position_key=k, account_key=account_key, symbol=v.symbol,
                                    original_positionAmt=v.positionAmt, 
                                    side="SELL" if v.position_side == "LONG" else "BUY",
                                    position_side=v.position_side, quantity=amt,
                                    old_price=float(getattr(v, 'mark_price', 0)),
                                    unique_id=f"NUKE_{int(now_ts)}",
                                    reason="ROGUE_EXPIRED_CLEANUP", is_full_close=True, action="CLOSE"
                                ))
                        else:
                            allowed_set.add(k)
                            try:
                                s = k.split(':')[1].replace('_LONG', '').replace('_SHORT', '')
                                symbols_active_set.add(s)
                            except Exception:
                                pass
            # F. Final Cleanup of Zombies from Persistence
            if zombie_hedges:
                # Remove from new_persistence so they don't reappear
                for z in zombie_hedges:
                    if z in new_persistence: del new_persistence[z]

            # Add to Global List
            final_tradeable_set.update(allowed_set)

        try:
            # Atomic Save Helper
            async def atomic_save(path, data):
                tmp = path.with_suffix(".tmp")
                async with aiofiles.open(str(tmp), 'w') as f:
                    await f.write(json.dumps(data))
                    await f.flush()
                    os.fsync(f.fileno())
                os.replace(tmp, path)

            await atomic_save(persistence_file, new_persistence)

            sorted_keys = sorted(list(final_tradeable_set))
            await atomic_save(tradeable_file, sorted_keys)

            sorted_symbols = sorted(list(symbols_active_set))
            await atomic_save(symbols_active_file, sorted_symbols)

            self.logger.info(f"[cleanup] ✅ Updated. Keys: {len(sorted_keys)}, Active Symbols: {len(sorted_symbols)}")

        except Exception as e:
            self.logger.error(f"[cleanup] Save failed: {e}")

