async def _check_recent_entry_protection(ctx: dict, indicators: dict, position, current_price: float, is_long: bool) -> Optional[Signal]:

    now = datetime.now(timezone.utc)
    # Define "Recent" threshold (e.g., 15 minutes)
    RECENT_THRESHOLD_MIN = 15.0
    
    mins_since_open = minutes_since(position.opened_at, now)
    mins_since_aug = minutes_since(position.last_augmentation_time, now)
    
    # --- 1. Immediate Augmentation Reversal Cut ---
    # If we added size recently and price goes below that add price immediately, cut the fat.
    if mins_since_aug < 10 and position.last_augmentation_price and position.last_augmentation_amount > 0:
        # Buffer to prevent noise stops (e.g., 0.15% below add price)
        fail_buffer = current_price * 0.0015
        
        aug_fail_long = is_long and current_price < (position.last_augmentation_price - fail_buffer)
        aug_fail_short = not is_long and current_price > (position.last_augmentation_price + fail_buffer)
        
        if aug_fail_long or aug_fail_short:
            # Only cut the amount we just added
            cut_qty = position.last_augmentation_amount
            ctx['logger'].warning(f"⚔️ [AUGMENT_FAIL_GUARD] {ctx['position_key']} Recent add failed. Price {current_price} crossed aug_price {position.last_augmentation_price}. Cutting {cut_qty}")
            return Signal(action='REDUCE', reason=f"AUGMENT_IMMEDIATE_FAIL (AugPrice: {position.last_augmentation_price:.2f})", conviction=100.0, reduction_amount=cut_qty)

    # --- 2. New Position Breathing Room (The DC_3M Shield) ---
    if mins_since_open < RECENT_THRESHOLD_MIN:
        dc_low_3m = indicators.get('dc_low_3m', 0)
        dc_high_3m = indicators.get('dc_high_3m', 0)
        
        # If indicators aren't ready, don't kill it yet
        if not dc_low_3m or not dc_high_3m:
            return None

        # LONG Logic
        if is_long:
            # If we are ABOVE dc_low_3m, we are safe, even if PnL is red.
            # Allow price to wiggle down to the band.
            if current_price >= dc_low_3m:
                # Log that we are shielding
                # ctx['logger'].info(f"🛡️ [NEW_POS_SHIELD] {ctx['position_key']} Holding above DC_LOW_3M ({dc_low_3m:.2f})")
                return None # Explicitly return None to BLOCK other stop loss logic
            else:
                # We broke the shield. HARD STOP.
                return Signal(action='CLOSE', reason=f"NEW_POS_BROKE_DC_LOW_3M ({dc_low_3m:.2f})", conviction=-100.0)
        
        # SHORT Logic
        else:
            if current_price <= dc_high_3m:
                # ctx['logger'].info(f"🛡️ [NEW_POS_SHIELD] {ctx['position_key']} Holding below DC_HIGH_3M ({dc_high_3m:.2f})")
                return None # Block other stops
            else:
                return Signal(action='CLOSE', reason=f"NEW_POS_BROKE_DC_HIGH_3M ({dc_high_3m:.2f})", conviction=-100.0)
    return None
#0B =============================================================================================================== MASTER STOP LOSS ===============================================================================================================
async def evaluate_master_stop_loss_new(ctx: dict) -> Optional[Signal]:
    logger = ctx['logger']
    service = ctx['service']
    account_key = ctx['account_key']
    position_key = ctx['position_key']
    position = service.positions.get(position_key)
    is_quick_trade = "QUICK" in (position.augment_reason or "").upper()
    now = datetime.now(timezone.utc)
    age_seconds = (now - position.opened_at).total_seconds() if position.opened_at else 999
    if is_quick_trade and age_seconds < 300:
        gain = ctx['gain']
        if gain > -1.2:
            i = ii(ctx['service'], ctx['symbol'])
            k_1m = i.get('stoch_k_1m', 50)
            if ctx['position_side'] == "LONG" and k_1m < 80:
                 logger.info(f"[{ctx['position_key']}] SHIELD ACTIVE: Holding through volatility (gain={gain}%)")
                 return None 
    try:
        symbol_min_qty = service.min_qty.get(position.symbol, 0.001)
        pos_min_qty = max( config.MIN_POSITION_SIZE / current_price, symbol_min_qty * 1.2)
        now_ts = time.time()
        last_seen = master_stop_last_seen.get(position_key, 0.0)
        if last_seen > 0.0:
            gap = now_ts - last_seen
            if gap > MASTER_STOP_STALE_SECONDS and now_ts - master_stop_last_alert.get(position_key, 0.0) >= MASTER_STOP_ALERT_COOLDOWN:
                logger.critical(f"[MASTER_STOP_MONITOR] {position_key} evaluate gap={gap:.1f}s>{MASTER_STOP_STALE_SECONDS:.0f}s count={master_stop_monitor_counter.get(position_key, 0)}")
                master_stop_last_alert[position_key] = now_ts
        count = master_stop_monitor_counter.get(position_key, 0) + 1
        master_stop_monitor_counter[position_key] = count
        master_stop_last_seen[position_key] = now_ts
        if count % 50 == 0:
            logger.info(f"[MASTER_STOP_COUNTER] {position_key} evaluat e_master_stop_loss_new count={count}")
        # position = service.positions_by_account.get(account_key, {}).get(position_key)
        try:
            master_stop_enter_count[position_key] = master_stop_enter_count.get(position_key, 0) + 1
            if master_stop_enter_count[position_key] % 10 == 1:
                reduced_minutes = minutes_since(getattr(position, 'last_reduction_time', None), datetime.now(timezone.utc)) if getattr(position, 'last_reduction_time', None) else None
                logger.info(f"[MMMMASTER_STOP_ENTER] {position_key} master stop loss start count={master_stop_enter_count[position_key]} reduced {reduced_minutes if reduced_minutes is not None else 'n/a'} min ago")
        except Exception as counter_err:
            logger.warning(f"[MASTER_STOP_ENTER] counter error {position_key}: {counter_err}")
        current_price = float(position.mark_price) if position.mark_price > 0 else await quick_price(ctx['symbol'])
        is_long = ctx['position_side'] == "LONG"
        config = ctx['config']
        gain = ctx['gain']
        min_required_qty = max(2 * config.MIN_POSITION_SIZE / current_price,  ctx['service'].min_qty.get(position.symbol, 0.001))
        if position.positionAmt < min_required_qty:
            logger.debug(f'{position_key} Position too small for stop loss')
            return None
        i = ii(ctx['service'], ctx['symbol'])
        if not i:
            return None
        # if await _is_in_cooldown_period(ctx, position):
        #     return None
        tier_mult = calculate_tier_mult(i, is_long)
        retention_qty = max(1, tier_mult) * pos_min_qty

        recent_signal = await _check_recent_entry_protection(ctx, i, position, current_price, is_long)
        if recent_signal:
            return recent_signal
        
        # If the position is new (<15m) and we didn't get a kill signal above, 
        # it means we are inside the DC bands.
        # We should skip generic PnL stops, but perhaps allow critical indicator stops.
        now = datetime.now(timezone.utc)
        if minutes_since(position.opened_at, now) < 15:
            # Check if we are safely inside bands
            dc_low = i.get('dc_low4_3m', 0)
            dc_high = i.get('dc_high4_3m', 0)
            if (is_long and current_price >= dc_low) or (not is_long and current_price <= dc_high):
                # We are safe inside the "Breathing Room".
                # Return None to preventing premature "tight stop" firing.
                return None 

        if position.positionAmt <= retention_qty * 1.05:
            logger.info(f"🛡️ [MASTER_STOP_BLOCKED] Keeping {position.positionAmt} (Floor: {retention_qty}) due to Stoch 1m/3m alignment.")
            return None

        stop_signal = await _check_critical_price_levels(ctx, i, position, current_price, is_long)
        if stop_signal:
            return stop_signal
        stop_signal = await _check_predefined_stop_levels(ctx, position, current_price, is_long)
        if stop_signal:
            return stop_signal
        stop_signal = await _check_technical_stop_conditions(ctx, i, position, current_price, is_long)
        if stop_signal:
            return stop_signal
        stop_signal = await _check_immediate_reduction_triggers(ctx, i, position, current_price, is_long)
        if stop_signal:
            return stop_signal
        stop_signal = await _check_aggressive_exit_conditions(ctx, i, position, current_price, is_long)
        if stop_signal:
            return stop_signal
        stop_signal = await _check_signal_driven_exits(ctx, i, position, current_price, is_long)
        if stop_signal:
            return stop_signal
        stop_signal = await _check_proactive_profit_taking(ctx, i, position, current_price, is_long)
        if stop_signal:
            return stop_signal
        stop_signal = await _check_trailing_stops(ctx, i, position, current_price, is_long)
        if stop_signal:
            return stop_signal
        stop_signal = await _check_account_specific_stops(ctx, i, position, current_price, is_long)
        if stop_signal:
            return stop_signal
        stop_signal = await _check_atr_stops(ctx, i, position, current_price, is_long)
        if stop_signal:
            return stop_signal
        stop_signal = await _check_momentum_stops(ctx, i, position, current_price, is_long)
        if stop_signal:
            return stop_signal
        logger.debug(f'{position_key} No stop loss conditions met - checked all conditions')
        if config.VERBOSE_STOPS:
            logger.info(f"[STOP_CHECK_SUMMARY] {position_key}: gain={gain:.2f}% price={current_price:.6f} k_15m={i.get('stoch_k_15m', 0):.1f} k_3m={i.get('stoch_k_3m', 0):.1f} ha_3m={i.get('ha_3m', 'neutral')} dc_basis_3m={i.get('dc_basis_3m', 0):.6f}")
                    
        return None
    except Exception as e:
        logger.error(f"CRITICAL: Exception in   for {position.symbol}: {e}")
        logger.error(traceback.format_exc())
        return None

async def _is_in_cooldown_period(ctx: dict, position) -> bool:
    """Check if position is in cooldown period"""
    now = datetime.now(timezone.utc)
    service = ctx['service']
    position_key = ctx['position_key']
    if position_key in service.recently_queued_signals:
        time_since_signal = now.timestamp() - service.recently_queued_signals[position_key]
        if time_since_signal < 20:
            return True
    if minutes_since(position.last_reduction_time, now) < 3:
        return True
    if minutes_since(position.last_augmentation_time, now) < 3:
        return True
    if minutes_since(position.opened_at, now) < 3:
        return True
    return False

async def _check_predefined_stop_levels(ctx: dict, position, current_price: float, is_long: bool) -> Optional[Signal]:
    """Check predefined stop loss levels"""
    position_key = ctx['position_key']
    service = ctx['service']
    stop_levels = await safe_get_stop_levels_data(position_key, service)
    if not stop_levels:
        return None
    position_value = abs(position.positionAmt * current_price)
    config = ctx['config']
    symbol_min_qty = service.min_qty.get(position.symbol, 0.001)
    pos_min_qty = max(2 * config.MIN_POSITION_SIZE / current_price, symbol_min_qty * 1.2)
    for idx, stop_level in enumerate(stop_levels):
        level = stop_level.get('level') if isinstance(stop_level, dict) else getattr(stop_level, 'level', 0.0)
        if not level or level <= 0:
            continue
        target_qty = pos_min_qty
        if idx == 0 and position_value > 200:
            target_qty = max(target_qty, 200.0 / current_price)
        elif idx == 0 and position_value > 50:
            target_qty = max(target_qty, 50.0 / current_price)
        reduction_amt = max(0.0, abs(position.positionAmt) - target_qty)
        if reduction_amt <= 0:
            continue
        if level and ((is_long and current_price < level) or (not is_long and current_price > level)):
            action_type = 'PROFIT_TAKE' if ctx['gain'] > 0.5 else 'REDUCE'
            logger.info(f"[STOP_HIT] {position_key}: {action_type} at {level:.6f}, current={current_price:.6f}")
            return Signal( action=action_type, reason=f"STOP_LOSS_HIT level={level:.6f} amt={reduction_amt:.6f}", conviction=95.0 if is_long else -95.0, reduction_amount=reduction_amt,  stop_levels=ctx.get('enforced_stop_levels') )
    return None

async def _check_immediate_reduction_triggers(ctx: dict, indicators: dict, position, current_price: float, is_long: bool) -> Optional[Signal]:
    """Check immediate reduction triggers based on stochastic and price action"""
    k_15m = indicators.get('stoch_k_15m', 50) or 50
    k_15m_prev = indicators.get('stoch_k_15m_prev', 50) or 50
    d_15m = indicators.get('stoch_d_15m', 50) or 50
    wt1_3m = indicators.get('wt1_3m', 0) or 0
    wt2_3m = indicators.get('wt2_3m', 0) or 0
    ha_3m = indicators.get('ha_3m', 'neutral') or 'neutral'
    t_up_3m = indicators.get('t_up_3m', False) or False
    high_3m = indicators.get('high_3m', 0) or 0
    high_3m_prev = indicators.get('high_3m_prev', 0) or 0
    low_3m = indicators.get('low_3m', 0) or 0
    low_3m_prev = indicators.get('low_3m_prev', 0) or 0

    if ctx['config'].VERBOSE_STOPS:
        logger.debug(f"[STOP_CHECK] {ctx['position_key']}: Checking immediate reduction triggers - k_15m={k_15m:.1f} k_15m_prev={k_15m_prev:.1f} d_15m={d_15m:.1f}")
