async def bootstrap_position_service(logger=None, accounts: Optional[Dict[str, Any]] = None, enable_auto_fetch: bool = True, trade_manager: Optional[Any] = None, start_maintenance: bool = True) -> PositionService:
    if logger: logger.info("[bootstrap] START")
    if accounts is not None:
        resolved_accounts = accounts
        if logger:
            logger.info(f"[bootstrap_position_service] Using provided accounts: {len(resolved_accounts)} accounts: {list(resolved_accounts.keys())}")
    else:
        resolved_accounts = await load_accounts_from_config(config, logger)
        if logger:
            logger.debug(f"[bootstrap_position_service] Loaded accounts from config: {len(resolved_accounts)} accounts: {list(resolved_accounts.keys())}")
    if not resolved_accounts:
        if logger:
            logger.error(f"[bootstrap_position_service] CRITICAL: No accounts available! Cannot create PositionService.")
        raise RuntimeError("No accounts available to create PositionService")
    if logger:
        logger.info(f"[bootstrap_position_service] Initializing PositionService with {len(resolved_accounts)} accounts: {list(resolved_accounts.keys())}")
    service = PositionService(logger=logger, accounts=resolved_accounts)
    if trade_manager:
        service.trade_manager = trade_manager 
    if logger:
        logger.info(f"[bootstrap_position_service] PositionService created, accounts dict has {len(service.accounts)} accounts: {list(service.accounts.keys())}")
    if logger: logger.info("[bootstrap] About to call initialize()")
    
    # FIX: Use start_maintenance flag
    if start_maintenance:
        asyncio.create_task(service._universe_maintenance_loop())
    else:
        if logger: logger.info("[bootstrap] Skipping universe maintenance loop (start_maintenance=False)")

    await service.initialize(force=False, enable_auto_fetch=enable_auto_fetch)
    if logger: logger.info("[bootstrap] initialize() completed")
    asyncio.create_task(service._enforce_data_sync_once())
    if logger: logger.info("[bootstrap] DONE, returning service")
    return service

if __name__ == "__main__":
    async def _run() -> None:
        # WARNING: If running directly, use ez_positions.py instead which has PositionsFetcher integrated
        # This entry point is for backward compatibility only
        service = await bootstrap_position_service(enable_auto_fetch=False)
        loop = asyncio.get_running_loop()
        # # --- MANUAL COMMANDS AREA ---
        
        # # Example: Add XRPUSDT to json files so it can't be overwritten/missing
        # await manual_position_data_persistence(service, "XAUUSDT", "ADD")
        
        # # Example: Remove an old symbol
        # await manual_position_data_persistence(service, "FLMUSDT", "REMOVE")
        
        # # ----------------------------
        async def _graceful_shutdown(reason: str) -> None:
            if service.logger:
                service.logger.info(f"[positions_service] Shutdown requested ({reason})")
            await service.shutdown()

        def _signal_handler(sig):
            logger.warning(f"[positions_service] 🛑 Signal {sig.name} received - shutting down immediately")
            asyncio.create_task(_graceful_shutdown(f"signal:{sig.name}"))
        for sig in (signal.SIGINT, signal.SIGTERM):
            try:
                loop.add_signal_handler(sig, lambda s=sig: _signal_handler(s))
            except NotImplementedError:
                pass
        try:
            iteration = 0
            while not service._shutdown_event.is_set():
                if iteration % 10 == 0:
                    try:
                        data_dir = Path(config.DATA_DIR) if hasattr(config, 'DATA_DIR') else Path.home() / 'binance' / 'data'
                        kill_flag = data_dir / '.kill_ez_positions_service'
                        if kill_flag.exists():
                            logger.warning(f"[positions_service] Kill flag file found - exiting cleanly for deployment")
                            try: kill_flag.unlink()
                            except Exception: pass
                            await _graceful_shutdown("kill_flag")
                            break
                    except Exception: pass
                try:
                    await asyncio.wait_for(service._shutdown_event.wait(), timeout=1.0)
                    break
                except asyncio.TimeoutError:
                    iteration += 1
                    continue
        except KeyboardInterrupt:
            await _graceful_shutdown("KeyboardInterrupt")
        finally:
            if not service._shutdown_event.is_set():
                await service.shutdown()

    restart_delay = 5
    while True:
        try:
            asyncio.run(_run())
            break
        except KeyboardInterrupt:
            break
        except Exception as exc:
            logger.exception(f"[positions_service] Fatal crash: {exc}. Restarting in {restart_delay}s")
            time.sleep(restart_delay)
            restart_delay = min(restart_delay * 2, 60)